quests[26337] = { id = 26337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating the Market", description = "<It's not hard to see why the Foebreaker is behind schedule. Every other day, a foreman comes in and changes the blueprints.>\n\n<Most troubling are the recent alterations. The workers have been ordered to remove rivets to save on costs!>\n\n<You'd better track down one of the Bilgewater foremen responsible for this and make an example out of him, before any Horde lives are lost in a faulty ship.>", sourceObjective = "Track down a Bilgewater Foreman somewhere in Bilgewater Harbor and knock him around a little.", completion = "So they were trying to skimp on production costs? Unacceptable!\n\nI'm glad you knocked some sense into them. If that foreman makes good on his word, our fleet will be ship-shape in time for the invasion.", sourceObjectiveStatus = "unverified-source-field" }
quests[26338] = { id = 26338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", sourceObjective = "Slay 7 Bloodscalp Mystics, 7 Bloodscalp Hunters, 7 Bloodscalp Scouts, and 1 Bloodscalp Beastmaster.", completion = "Balance is restored - for now.  We may call on you again in the future, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26339] = { id = 26339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Staging in Brewnall", description = "While High Tinker Mekkatorque, his military advisors, and I finalize the plans for the attack on Razlo Crushcog, I've sent my assistant ahead to Brewnall Village to begin preparations.\n\nTo get to Brewnall Village, follow the road southeast out of town. Once you arrive, find Jarvi Shadowstep and see if he needs any help. Our dwarven cousins have dispatched a cadre of mountaineers from Ironforge to join us in the fight against Crushcog.", sourceObjective = "Speak with Jarvi Shadowstep at Brewnall Village.", completion = "Ah, yes, Kelsey told me to expect you. There's still much to do before we can take on Crushcog.", sourceObjectiveStatus = "unverified-source-field" }
quests[26340] = { id = 26340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunt", description = "Of all the places to end up across Azeroth, I'm stuck here in Grom'gol.  With the marauding wildlife, the caravan raids, and the constant threat of troll attacks, I'm surprised I've survived for this long.\n\nCould be worse, I suppose.  At least here in Grom'gol we have walls and guards.  There's a group of hunters up north that set up camp right in the middle of the jungle!\n\nI see people heading there all the time.  If you're looking for trouble, feel free to head up there.  I'll stick with my Grom'gol.", sourceObjective = "Report to Barnil Stonepot at Nesingwary's Expedition in Northern Stranglethorn.", completion = "Hmm?  Barnil's the name.  And you are...?", sourceObjectiveStatus = "unverified-source-field" }
quests[26341] = { id = 26341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stone Shards", description = "I've scouted all over these highlands, {name}, and there's one thing I've found I haven't been able to explain.\n\nTo the northeast of here, there's a circle of stones, like the others you'll find everywhere in Arathi... but the largest and most imposing of them, built into the mountainside itself.\n\nJust between you and me, I heard voices while I was there. Whispers of the earth. If you're the curious type, you could go see for yourself...", sourceObjective = "Investigate the Shards of Myzrael.", completion = "<The shards pulse softly, and a whisper slowly echoes through your head.>\n\nHelp...", sourceObjectiveStatus = "unverified-source-field" }
quests[26342] = { id = 26342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint it Black", description = "We have reliable intelligence that Razlo Crushcog has taken up a defensive position on the island in the middle of frozen Iceflow Lake. To make matters worse, he's surrounded himself with a network of sentry-bots that will detect any possible attackers.\n\nIf we're to take on Crushcog, we'll need to take out those sentries. This device launches a dark, sticky paint that will coat the optical sensors of Crushcog's sentry-bots. Use it to take out his early warning system.", sourceObjective = "Use the Paintinator to blind 5 of Crushcog's Sentry-Bots.", completion = "You've given us just the opening we'll need to get the drop on Crushcog. Excellent work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26343] = { id = 26343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in Northern Stranglethorn.", sourceObjective = "Bring 2 Large River Crocolisk Skins to Drizzlik at Nesingwary's Expedition.", progress = "My equipment is all ready to go, {name}, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?", sourceObjectiveStatus = "unverified-source-field" }
quests[26344] = { id = 26344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", sourceObjective = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik at Nesingwary's Expedition.", progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, {name}. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside.", sourceObjectiveStatus = "unverified-source-field" }
quests[26345] = { id = 26345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder snapjaw crocolisk.  Find them to the south, near the border with the cape.", sourceObjective = "Bring an Elder Crocolisk Skin to Drizzlik at Nesingwary's Expedition.", progress = "I read somewhere that the elder crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder snapjaw crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!", sourceObjectiveStatus = "unverified-source-field" }
quests[26346] = { id = 26346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Skuerto of what you've done so far.", sourceObjective = "Return to Skuerto at Refuge Pointe in Arathi Highlands.", completion = "Say no more, {name}. I followed up with an... \"old friend\" while you were gone. I should've known better than to send you to those shards.\n\nWe've both made a grave mistake in involving ourselves in this. Luckily, I \"persuaded\" my boy Gerrig to tell me what to do if this happened.", sourceObjectiveStatus = "unverified-source-field" }
quests[26347] = { id = 26347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me chasm ooze from the slimes in the Raging Chasm to the northeast.", sourceObjective = "Bring 5 Chasm Oozes to Captain Grayson at the Westfall Lighthouse.", progress = "The flame will not burn for long without ooze, {name}. We used to use oil back in the day, but it was hard to come by!", completion = "Praise you, brave {class}.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny.", sourceObjectiveStatus = "unverified-source-field" }
quests[26348] = { id = 26348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill murloc tidehunters and oracles and I will see to it that you are rewarded.", sourceObjective = "Kill 7 Murloc Tidehunters and 7 Murloc Oracles.", completion = "Well done, {name}.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place.", sourceObjectiveStatus = "unverified-source-field" }
quests[26349] = { id = 26349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", sourceObjective = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, {name}.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics.", sourceObjectiveStatus = "unverified-source-field" }
quests[26350] = { id = 26350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priestess Hu'rala", description = "Thank you, {name}.  I know you didn't have to save my life, and... well, I am thankful.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe trolls at Bambala in the east may know more.  Speak with their priestess.", sourceObjective = "Speak with Priestess Hu'rala at Bambala in Northern Stranglethorn.", completion = "Mandokir is alive, yes.\n\nYou are responsible, yes.\n\nYou may be able to stop him still, yes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26351] = { id = 26351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go west, and you will find the feathers, yes.", sourceObjective = "Obtain 5 Jungle Stalker Feathers from Jungle Stalkers in Northern Stranglethorn.", progress = "Raptor named Ohgan'aka, still your friend.", completion = "You bring feathers, yes.\n\nYou can follow directions, yes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26352] = { id = 26352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cozzle's Plan", description = "I may be of Darkspear birth, but I spent my childhood here, in Stranglethorn Vale.  I've seen everything there is to see here in Stranglethorn, but the most offensive is the devastation that the Venture Company has done to the riverbed.\n\nTo make things worse, Foreman Cozzle and his crew have been increasing their activity, and I suspect they have some new plan.  Succeed where I failed, {name}: Kill Cozzle, obtain his key, and steal the blueprints from his apartment.", sourceObjective = "Obtain Cozzle's Key from Foreman Cozzle, then obtain the Fuel Regulator Blueprints.", progress = "The Venture Company's acts against Stranglethorn cannot be forgiven.", completion = "A fuel regulator?  This seems important.  At least, I hope it is.\n\nWe may not have ended the Venture Company's operations, but we at least slowed them down.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26353] = { id = 26353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", sourceObjective = "Find Captain Sanders' footlocker and search it for the next clue.", completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!", sourceObjectiveStatus = "unverified-source-field" }
quests[26354] = { id = 26354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", sourceObjective = "Find the old barrel near the ruined chimney and search it for your next clue.", progress = "This looks like the right barrel.", completion = "Good work, treasure hunter!", sourceObjectiveStatus = "unverified-source-field" }
quests[26355] = { id = 26355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", sourceObjective = "Search the empty jug next to the windmill for the next clue.", progress = "There's a clue sticking out of the empty jug.", completion = "You're on your way to the jackpot, treasure seeker!", sourceObjectiveStatus = "unverified-source-field" }
quests[26356] = { id = 26356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Sanders' Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", sourceObjective = "Locate Captain Sanders' chest and open it for your reward.", progress = "The lost treasure of Captain Sanders awaits!", completion = "The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.\n\nCongratulations!", sourceObjectiveStatus = "unverified-source-field" }
quests[26357] = { id = 26357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. The spirits not gonna be watchin' over them much longer.\n\nTake this torch with ya as ya fight through the Vilebranch, {class}. Set fire to their tiki masks. I'll be watchin' from here as their wards and hexes fade away, an' their heretical dark voodoo goes up in smoke.", sourceObjective = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", progress = "I don't see enough lights burnin', {class}. Better get goin'.", completion = "Such a pretty site ta see the enemy's hopes burnin'...", sourceObjectiveStatus = "unverified-source-field" }
quests[26358] = { id = 26358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready the Air Force", description = "I gave Hellscream my personal guarantee that I'd have his airfleet ready this week, but our flagship - The Spear of Durotar - still doesn't have its primary engines installed.\n\nFleep promised me a dangerously shiny new engine last week. Go to her junkyard behind the bank and find out what the holdup is.\n\nThe airfleet is waiting on us, {name}!", sourceObjective = "Look for Fleep at her junkyard within Bilgewater Harbor in Azshara.", completion = "<Fleep wipes her face, plastering an enormous grease smear across her cheek.>\n\nWhat? The Captain said WHAT?\n\n<She shakes her pipe wrench threateningly.>\n\nIt's HIS fault this big beast of an engine is delayed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26359] = { id = 26359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", sourceObjective = "Speak with Priestess Hu'rala at Bambala to participate in the Mind Vision ritual.", completion = "What did Priestess tell you?\n\nThe raptor is daughter of Ohgan, heir to Mandokir's seat.\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26360] = { id = 26360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", sourceObjective = "Obtain Braddok's Big Brain from Braddok in Zul'Mamwe.", progress = "Extra-big spells need extra-big brains, yes.", completion = "Hold on, next part is tough, yes.\n\nLots of chances to fail, yes.\n\nBut {name} and {name}'aka going to be reunited... yes they will.", sourceObjectiveStatus = "unverified-source-field" }
quests[26361] = { id = 26361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoot's Samophlange", description = "It was the Captain who insisted his new engines use an induction samophlange.\n\nThose things hadn't even been invented yet!\n\nI tasked Smoot with creating one based on some stolen Venture Company schematics, and he's finally built a working model.\n\nNow that he's got his samophlange, he's drunk with power. He's running all over town with it like a goblin possessed.\n\nSmack Smoot and snag my samophlange, {name}.", sourceObjective = "Find Smoot somewhere in Bilgewater Harbor. Tackle him and get the Induction Samophlange.", progress = "Smoot's a good engineer.\n\nA samophlange can kill from thirty yards if you misalign the reduction caliphracts.", completion = "Excellent! I should have this here engine samophlanginated within the hour.", sourceObjectiveStatus = "unverified-source-field" }
quests[26362] = { id = 26362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", sourceObjective = "Speak with Priestess Hu'rala, then help the Captured Lashtail Hatchling escape from Zul'Gurub.", completion = "What a shame, yes.\n\nThis is what the spirits wanted, yes.\n\nMaybe when you are stronger, you will go into Zul'Gurub and take back your {name}'aka from Mandokir, yes.\n\nFor now, Priestess give you this.", sourceObjectiveStatus = "unverified-source-field" }
quests[26363] = { id = 26363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summit of Fate", description = "You've done well cleaving through their warriors, {name}. I'd like you to investigate the summit of Jintha'Alor.\n\nWe were prepared for our fiercest battle there, to storm their dark altar, but it's too quiet. Not a sound. It could be a terrible trap, and someone strong should look into it first instead of all of us rushing in.\n\nAnd if it's not a trap... I'm very interested in finding out what happened up there. Bring me back any clues you can find.", sourceObjective = "Collect 8 Spider Idols from the Vilebranch at the summit of Jintha'Alor.", progress = "What did you find?", completion = "Dead? All of them, around the altar? And you found these spider idols on them...\n\nA mass sacrifice. They threw their lives to Shadra.", sourceObjectiveStatus = "unverified-source-field" }
quests[26364] = { id = 26364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down with Crushcog!", description = "Our cousins, the dwarves of Ironforge, have agreed to help us in the battle against Razlo Crushcog. Mountaineer Stonegrind is a veteran who knows Dun Morogh well. He and High Tinker Mekkatorque stand ready on a small snow-covered island in Iceflow Lake to the north. Meet up with them there and let the high tinker know when you are ready to face the traitor Crushcog.\n\nTake this orbital targeting device and use it during the battle. It will help guide the high tinker's special weapons.", sourceObjective = "Defeat Razlo Crushcog. Speak to High Tinker Mekkatorque at Iceflow Lake when you are ready to begin the battle.", progress = "Did you face Crushcog? What happened?", completion = "We're finally free of Razlo Crushcog and his interference! With the defeat of Crushcog and his forces, Thermaplugg can't afford to send any more of his followers to the surface. I can't wait for the day when we defeat him for good!", sourceObjectiveStatus = "unverified-source-field" }
quests[26365] = { id = 26365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Redridge Mountains!", description = "While the situation here is dire, other parts of the region are literally quaking from the great upheaval.\n\nI have here a report from Watch Captain Parker of Redridge Mountains, one of our territories east of Elwynn Forest. He is asking for a hero to come to their aid.\n\nWe are spread so thin here that I don't know how we can afford to send anymore military. Would you check on Parker and see what he needs? You will find Watch Captain Parker atop the tower at Three Corners.", sourceObjective = "Report to Watch Captain Parker at Tower Watch in Redridge Mountains.", completion = "Heard Westfall was in some deep doody.\n\n<Parker doesn't even turn to face you.>\n\nWell, we got our own set of problems here. See them gnolls out there? Looks like they're actin' up again. I don't like it. Don't like it one bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26366] = { id = 26366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heads Up", description = "Umboda of the Vilebranch is one of their strongest warriors, and a sick butcher.\n\nHe takes the heads of all he slays as trinkets, rewards...even weapons!  It's his turn to be taken.\n\nFind Umboda \"Three-Heads\", slay him, and bring me HIS head! We'll see how the Vilebranch fight when we throw it back over their walls!", sourceObjective = "Defeat Umboda Three-Heads and collect his head.", progress = "Let's see it!", completion = "The look of fear and confusion on his face... this is what he deserved! Let's make sure all the Vilebranch wear the same look.", sourceObjectiveStatus = "unverified-source-field" }
quests[26367] = { id = 26367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longo's Revenge", description = "Ongo'longo was one of us. What outsiders called a Dire Troll, but he was a Revantusk, and a proud warrior like all of us!\n\nThen the Vilebranch took him. They keep him chained up in a pit at the top of Jintha'Alor, made to dance for their sick amusement.\n\nNo chains can hold Ongo'longo. All you need to do is raise his temper, {name}. Fight him until he's enraged enough to remember his true spirit and break free... and then get out of the way!", sourceObjective = "Fight Ongo'longo until he breaks free.", completion = "I wish I could have been there to see it, {name}! I'll have to hear the story from Ongo'longo himself when this is over.", sourceObjectiveStatus = "unverified-source-field" }
quests[26368] = { id = 26368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomous Secrets", description = "There's more of this curious venom to be had if Shadra's being summoned.\n\nDon't look so surprised... the Forsaken have studied these lands before, and we've encountered the venom queen at least once. Her toxins have proven quite useful in the past.\n\nThey'll prove useful to the Horde once more, too. Be a dear and fetch me as much poison as you can from the spawn of Shadra that lurk in the cave on the summit... I'm sure you'll be covered in it anyway.", sourceObjective = "Collect 6 Shadra-Spawn Venom Samples from the Spawn of Shadra in Jintha'Alor.", progress = "Have you the venom...?", completion = "Mmm, yes... that old nostalgic smell.\n\nYou've done well for the Forsaken, and the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[26369] = { id = 26369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Keeper", description = "Kotonga has told me of Shadra. She is the venom queen, the loa of spiders, worshipped in darkness. If the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", sourceObjective = "Kill Morta'gya the Keeper and obtain the Tablet of Shadra.", progress = "Be sure you search her body. I don't want any traps laid by the Vilebranch to be hidden by their deaths.", completion = "The parts scattered, the keepers separated... I see.\n\nThis is a ritual to summon Shadra. They must not have gotten far. It should be destroyed...", sourceObjectiveStatus = "unverified-source-field" }
quests[26370] = { id = 26370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sentinel Hill", description = "The Defias Brotherhood are not a force to be taken lightly, {name}. What you witnessed was the birth of a ruthless organization of criminals that will stop at nothing to see Stormwind turned to rubble.\n\nI need you to return to Sentinel Hill and let Gryan know that I am sending him troops. I hope it's not too late.", sourceObjective = "Report to Marshal Gryan Stoutmantle at Sentinel Hill in Westfall.", completion = "Five years of work burned to the ground in five minutes. Damn the Defias!\n\nAnd this is only the beginning, {name}! We have a long, hard road ahead of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26371] = { id = 26371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Captain Grayson", description = "Have you heard of Captain Grayson? Some say that he's the figment of a drunken sailor's imagination, but anyone in Westfall will tell you that Grayson is real! He's a ghost that haunts the Westfall Lighthouse far to the west, off the coast of the Longshore.\n\nDo you dare investigate?", sourceObjective = "Find Captain Grayson at the Westfall Lighthouse in Westfall.", completion = "Aye... I used to be flesh and blood, just like you, lad. That is, until that fateful day when the murlocs attacked the lighthouse...", sourceObjectiveStatus = "unverified-source-field" }
quests[26372] = { id = 26372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pre-Flight Checklist", description = "This new engine is extremely fast. And dangerous. I'd use the word \"volatile.\"\n\nThat's the way the Captain likes it.\n\nRun back up the hill and let him know that I'll install this bad boy right now and that he should meet me at the construction site.", sourceObjective = "Talk to Captain Krazz at Bilgewater Harbor in Azshara.", completion = "My airship has engines? At last!\n\nNow we can rip the heavens a new one!\n\nOnce the ground and naval forces are ready, we're going to light up the skies over the Twilight Highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[26373] = { id = 26373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On to Kharanos", description = "Some of the mountaineers under Stonegrind's command were telling me about the situation out at Kharanos. When the troggs took over Frostmane Hold, it sounds like the surviving trolls fled westward, deep into the heart of the dwarven homeland.\n\nNow, they threaten the dwarven town of Kharanos. It sounds like they're going to need all the help they can get. You should go to Kharanos and introduce yourself to Captain Tharran. Just follow the road east out of Brewnall and keep going until you see the town.", sourceObjective = "Speak with Captain Tharran in Kharanos.", completion = "If Gnomeregan Covert Operations is recommending you, then you must have made quite an impression. Your help will be most welcome here, as we've a wealth of enemies and few enough mountaineers to face them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26374] = { id = 26374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ready the Ground Troops", description = "It was a bad idea to muster the troops in this festering goblin metropolis. Every vice that coin can buy is within arm's reach. Our mighty veterans are running rampant, blowing years of Northrend back-pay in a city-wide debacle.\n\nCan you make a sweep through the city and gather up any stragglers that have gone AWOL?\n\nMy axebite warriors are unmatched on the battlefield, but I won't have them disgrace their uniforms while on shore leave.", sourceObjective = "Search Bilgewater Harbor and convince 12 AWOL Grunts to report for duty.", completion = "Thank you, {name}! Most of my soldiers have already reported for duty, some a little worse for the wear.\n\nOne night in Bilgewater makes a hard orc humble.\n\nStill, fresh fighting in the Twilight Highlands should restore discipline.", sourceObjectiveStatus = "unverified-source-field" }
quests[26375] = { id = 26375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loose Stones", description = "The Twilight Cultists are taking my rocklings among them.  They drain them and torture them.  Strip them of the very essence that animates them from the stone.\n\nPlease, {race}, free my rocklings. Neither Diamant nor I have the delicacy to smash their chains without hurting them as well.  But we do have a tool you might use.\n\nUse this. Break their chains and set them free.", sourceObjective = "Use the Delicate Chain Smasher to release 6 Quartz Rocklings.", progress = "It is unbearable to watch. They know no mercy. They should be offered none.", completion = "You are a generous {race}. You give back to the earth that offers you so much. You have my respect. You shall surely have the respect of the Stone Lords with time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26376] = { id = 26376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred Runs Deep", description = "I would apologize for Boden, but stone is stubborn.\n\nIt does not sway from its ways without the wear of time.\n\nThe Stone Lords, Boden and I among them, are charged with retrieving the World Pillar.\n\nIn that, we are at odds.\n\nI would extend my patience upon you, {race}.\n\nProve that you are no ally of the Twilight Cult or Deathwing...\n\nCarry our hatred upon them.\n\nStrike swiftly where we cannot.\n\nSucceed and I will listen.", sourceObjective = "Kill Dragul Giantbutcher and 12 Twilight Cultists at Lorthuna's Gate.", progress = "Take your time, fleshling.\n\nI am in no hurry.", completion = "I have observed you, {race}.\n\nYou do not fear shedding Twilight blood.\n\nIn this, I am willing to extend you some degree of trust.\n\nIt is a start.\n\nAll things in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26377] = { id = 26377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsolid Ground", description = "The Twilight Cult are mining jade crystals near their camp.\n\nFoolish...\n\nReckless...\n\nGather the mined crystals. Take them to the center of their camp. Shatter them against the ground.\n\nThe reverberations and the powered crystal will bring the tunnelers upon them.\n\nThey will learn respect for the earth...\n\nPiece by piece...\n\nRock by rock...\n\n...with time.", sourceObjective = "Gather 6 Jade Crystal Clusters, combine them, and shatter them within the Lorthuna's Gate encampment.", progress = "BThey will learn respect for the earth...\n\nPiece by piece...\n\nRock by rock...\n\n...with time.", completion = "Time brings respect to all.\n\nThe smallest pebble.\n\nThe largest mountain.\n\nThe most stubborn cultist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26378] = { id = 26378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Westfall!", description = "Westfall has fallen to hard times, friend. With the threat of the Defias extinguished, the region has become a haven for the homeless and downtrodden. The crime rate of the area has skyrocketed as people fight for shelter and food. Now I hear tale of murder!\n\nIf you are interested in helping the people of the Alliance, Westfall would be a great place to start. Report to Lieutenant Horatio Laine at the Jansen Stead. You'll find Westfall directly west of Elwynn Forest.", sourceObjective = "Report to Lieutenant Horatio Laine at the Jansen Stead in Westfall.", completion = "Murder, rookie. That's what you're looking at on the ground in front of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26379] = { id = 26379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Aid of the Refugees", description = "You're come to help, I hope? You have no idea what I'm talking about, do you...\n\nI don't have time to fill you in on all of the details, but we had a town in Darkshore, Auberdine, that took some of the worst of the Cataclysm. We're in the process of rescuing some of the survivors, but I need someone with a bit more experience--someone like you--to check in on a refugee camp that we heard about in the south.\n\nLeave things to us up north. Head straight down there and help the refugees however you can.", sourceObjective = "Sentinel Lendra at Lor'danel wants you to speak to Priestess Alinya at the Refugee Camp.", sourceObjectiveStatus = "unverified-source-field" }
quests[26380] = { id = 26380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound for Kharanos", description = "I was supposed to be bringing these casks of ale to the inn in Kharanos. They contain a mysterious new ale produced by an upstart brewery based in Brewnall Village. As I was leaving town, I was attacked by a Frostmane troll raiding party. It's going to take me days to repair the wagon!\n\nI don't suppose you'd be willing to do me a favor, will you? These big kegs aren't going anywhere, but I have some smaller sample casks. Would you bring them to Kharanos for me? Just follow the road to the southeast.", sourceObjective = "Bring the Sample Casks to Innkeeper Belm at the Thunderbrew Distillery in Kharanos.", progress = "Welcome, visitor. Have you come to the inn to rest, or do you need a new hearthstone?", completion = "These look promising. I've heard great things about the Short and Stout Brewery, but I haven't had the chance to try their ale until now.\n\nWhile you're here, relax a little. If you need a spare hearthstone or wish to make Kharanos your home, just speak to me and I'll be happy to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[26381] = { id = 26381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Shadra", description = "Shadra must be summoned, for certain. To allow an opportunity like this to pass us by would be foolish. While the apothecaries can make fine use of the god's venom, they are relatively inexperienced in ritual magic.\n\nFortunately, I am quite familiar with preparing dark convocations. You will bring the scattered parts of Shadra to me, and I will help you bring her to this plane to be taken out.\n\nThe first part is the eye of Shadra, guarded in Agol'watha to the north.", sourceObjective = "Recover the Eye of Shadra from Agol'watha.", progress = "If the tablet was a ruse, I will not be pleased. Did you find the eye?", completion = "I'm pleased, {name}. That was quicker than I expected.", sourceObjectiveStatus = "unverified-source-field" }
quests[26382] = { id = 26382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can't Make An Omelette Without...", description = "Marnal has been pestering me about this Shadra plot for days. I'm almost upset he actually found the tablet; I was ready for him to shut up about it.\n\nDespite his high talk of ritual magic, he's still going to need my help as much as I need his. I've got to whip up a base medium with similar...\n\n...You know what, I'm not going to bother rambling about the details. Just bring me the Shadraspawn eggs from Agol'watha. There should be quite a few, guarded by the Vilebranch trolls.", sourceObjective = "Collect 5 Shadraspawn Eggs from Agol'watha.", progress = "I hope you brought enough.", completion = "Good, good. Just put them over there, I've got my hands full.", sourceObjectiveStatus = "unverified-source-field" }
quests[26383] = { id = 26383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Waves of Change", description = "You! You look able. And perhaps willing to help?\n\nAuberdine has finally fallen. Though many of its inhabitants departed long ago when the city first suffered the brunt of the Cataclysm, many of the more stubborn residents are yet unaccounted for. And it now appears that the city may have been overrun by water elementals.\n\nMy sisters need help rescuing the survivors. Please, {class}, use the western tree to reach Rut'theran, then speak to Vesprystus to secure a flight to Lor'danel. Be swift!", sourceObjective = "Use the teleportation tree in western Darnassus to reach Rut'theran Village, then speak to Vesprystus to secure a ride to Lor'danel.", completion = "Did the sentinels send you? Thank Elune. We need everyone we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[26384] = { id = 26384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkcleric Marnal", description = "We can't toss that tablet aside just yet, {name}. We can use it...\n\nYou see, I'm quite taken with the venom of the spiders here. It's clearly magical, probably related to that spider-god the trolls are involved with. And if that tablet will allow someone to summon it...\n\nWell, you can see where this is going. The Horde can't pass up this opportunity. Take the tablet to my fellow Forsaken. They're to the west, at the research station in the Hiri'watha ruins.", sourceObjective = "Bring the Tablet of Shadra to Darkcleric Marnal.\n\nProvided item:", completion = "Ah, what have we here...\n\nFascinating. Quite fascinating.", sourceObjectiveStatus = "unverified-source-field" }
quests[26385] = { id = 26385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Waves of Change", description = "It seems you have your first charge. You must travel back down to Rut'theran Village, where we first arrived, and speak to Vesprystus to secure a ride to Lor'danel.\n\nOnce in Lor'danel, aid the night elves in any way that you are able. I am trusting you to treat them with the reverence that they deserve in light of all that they have done for us.\n\nI must travel to the distant city of Stormwind to meet with King Varian. I hope to see your face again very soon, {name}. Until then, a fond farewell.", sourceObjective = "Speak to Vesprystus in Rut'theran Village to secure a ride to Lor'danel.", completion = "Our allies have come to our aid? Thank Elune. Tyrande was wise to extend open arms to your people.\n\nWe need help.  We need everyone we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[26386] = { id = 26386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surkhan", description = "Priestess is not very good at speaking Orcish, no.\n\nMaybe you go speak with Surkhan, upstairs.\n\nTell him about what you've seen inside Zul'Gurub, yes.", sourceObjective = "Report to Surkhan at Bambala in Northern Stranglethorn.", completion = "<You explain to Surkhan what has happened up to this point.>\n\nIt would seem that Jin'do has survived, and he is rallying his brothers to once again summon Hakkar into this world.  It was good of you to come to speak with me.\n\nThere is not much we can do now but to wait, and watch.  Jin'do is weak, and prime for striking, but I must wait for word from Rastakhan before issuing orders.  Until then, you and your raptor will have to wait.", sourceObjectiveStatus = "unverified-source-field" }
quests[26387] = { id = 26387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starvation Diet", description = "The spiders infesting the Creeping Ruin to the east are useless. We're calling them shadraspawn now, and it's clear they're related to the spider god, but that doesn't change the fact that they're more trouble than they're worth. I'd much rather just wipe the little pests out.\n\nWhen you head to the creeping ruin, destroy any cocoons you find. They feed off the bodies inside for days, so depriving them of their meal will be much more effective than trying to squash them all.", sourceObjective = "Destroy 6 Cocooned Victims at the Creeping Ruins.", completion = "Now we've got a win-win situation. The spiders are going to either starve off, or find some dwarves and elves to replenish their larder, since my colleagues and I would make a poor meal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26388] = { id = 26388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Skies", description = "Okay, you're all checked in. Wait here for Captain Krazz to bring the zeppelin around, then get on board and accompany the air fleet. Admiral Stonefist will be waiting for you outside of Dragonmaw Port!", sourceObjective = "Accompany the Horde air fleet to Twilight Highlands. Catch your zeppelin from the tower at the Southern Rocketway Terminus in Azshara.", progress = "You're here - but what about the airfleet?\n\nWhat happened to the fleet?", completion = "This is a disaster, {name}!\n\nOur air fleet was decimated. And reports are coming in that our navy was attacked - unprovoked - by the Alliance in open water.\n\nAnd what of Hellscream? Is the Warchief dead?", sourceObjectiveStatus = "unverified-source-field" }
quests[26389] = { id = 26389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Invasion", description = "The orcs have begun burning down the forest, {name}! They have taken over the vineyard to the east and are planning their final assault against us! They must be stopped!\n\nHead east, across the river, and kill the rampaging Blackrock orcs. Collect their weapons as proof of their demise and return to me.\n\nYou're our only hope, {name}!", sourceObjective = "Recover 8 Blackrock Orc Weapons.", progress = "Have you killed the rampaging orc hordes?", completion = "The Blackrock orcs will surely fall now that their main force has been defeated! Only one task remains.", sourceObjectiveStatus = "unverified-source-field" }
quests[26390] = { id = 26390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Invasion!", description = "The rampaging orc horde is lead by a savage beast known as Kurtok the Slayer! Kurtok is responsible for the recent invasion and must be killed if we are to have peace in the valley.\n\nVenture back east, across the river and through the vineyard, and look for the passage leading into the mountains. Kurtok will be there, preparing for another assault. Kill him and return to me.", sourceObjective = "Kill Kurtok the Slayer.", progress = "Have you found Kurtok?", completion = "With Kurtok slain we are safe once again from the orcish hordes. I will send peasants to the pass in an attempt to seal the passage so that no more orcs may come through into our territory.\n\nYou have the thanks of Stormwind and of the Alliance, hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[26391] = { id = 26391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguishing Hope", description = "Times like these make me long for when the Defias were still around. The cataclysm has opened a pathway from the Burning Steppes and now Blackrock orcs pour into Northshire Valley! They have taken over my vineyard and are burning it to the ground! TO THE GROUND!\n\nPlease, {name}, that vineyard is all I have. Take my fire extinguisher and extinguish the flames at the vineyard. There still might be hope for that land!", sourceObjective = "Use Milly's Extinguisher to put out 8 Vineyard Fires.", progress = "Have you put out the fires?", completion = "Bless your heart, {name}. You truly are a hero of the Alliance! Though the land is completely incinerated and there is nothing left of the vineyard but ash and debris, I still might be able to recover. Right? How bad can it be?", sourceObjectiveStatus = "unverified-source-field" }
quests[26393] = { id = 26393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Message", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Bartlett the Brave, our gryphon master.  He's just outside of the smithy; bring him my note, and then take a gryphon to Stormwind.", sourceObjective = "Bring Argus' Note to Bartlett the Brave the gryphon master.", progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!", sourceObjectiveStatus = "unverified-source-field" }
quests[26394] = { id = 26394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue to Stormwind", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", sourceObjective = "Buy a gryphon ride from the gryphon master Bartlett the Brave, then bring Argus' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Smith Argus?  I'm not surprised he needs more gear.  There are so many new recruits these days.\n\nWell thank you, {name}.  Here's some money to cover your travel costs.", sourceObjectiveStatus = "unverified-source-field" }
quests[26395] = { id = 26395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Longdrink", description = "{name}, I gathered into this crate everything Argus asked for.  Can you take it to him?\n\nIf you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Argus as fast as you can.  We don't want our fighting men and women in Goldshire to go without fresh equipment!", sourceObjective = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Goldshire, eh?  People sure are getting lazy. Have you been to Goldshire before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!", sourceObjectiveStatus = "unverified-source-field" }
quests[26396] = { id = 26396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Argus", description = "The gryphon master in Goldshire is Bartlett.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Bartlett, so just speak with me again when you're ready to take a gryphon to Goldshire.  Once there, you can deliver Osric's Crate to Smith Argus.", sourceObjective = "Buy a gryphon ride to Goldshire from the gryphon master Dungar Longdrink, then take Osric's Crate to Smith Argus at Goldshire.", progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, {name}.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Goldshire often!", sourceObjectiveStatus = "unverified-source-field" }
quests[26397] = { id = 26397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk With The Earth Mother", description = "Much has changed outside of Mulgore, {name}. The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do.\n\nYou must go, {name}, and be this example. Go to Orgrimmar. Tell Warchief Hellscream how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, and never forget your people.", sourceObjective = "Take the Mark of Bloodhoof to Garrosh Hellscream, located in Grommash Hold in Orgrimmar.\n\nYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin.", progress = "What makes you seek the Warchief of the Horde, {race}?", completion = "The Grimtotem forced from Mulgore... if Baine speaks for this, you are indeed a fierce warrior.\n\nFrom this day, your strength is no longer your own. It belongs to me, and the Horde, as a weapon of war.\n\nHellscream's eyes are upon you, {name}. Victory or death!", sourceObjectiveStatus = "unverified-source-field" }
quests[26398] = { id = 26398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walk With The Earth Mother", description = "You have fought bravely alongside me, {name}, and done much for my people. If every {race} could be as noble, the future of the Horde might not disturb me so much.\n\nI would ask you to ease my worries further. Go to Orgrimmar. Tell Warchief Hellscream how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, friend.", sourceObjective = "Take the Mark of Bloodhoof to Garrosh Hellscream, located in Grommash Hold in Orgrimmar.\n\nYou may speak with Tal the Wind Rider Master to travel there, or wait for the zeppelin.", sourceObjectiveStatus = "unverified-source-field" }
quests[26399] = { id = 26399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that some {race} schmuck in a ridiculous {class} getup found this ogre hand, and...\n\n<Skeezy trails off as he looks you over.>\n\nWhat was I just saying?  Oh yes... some <SWASHBUCKLING HERO/BREATHTAKING HEROINE> found this ogre hand, and Mok'thardin thinks it means that the ogres have some special artifact.  I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", sourceObjective = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", progress = "Why is it that the OGRES always find the priceless artifacts?", completion = "<Skeezy struggles fruitlessly to open the box.>\n\nThose ogres really know how to close a treasure chest, I'll tell you what.  A box is useless to me, hero.  We're going to need to find a way into this crate.", sourceObjectiveStatus = "unverified-source-field" }
quests[26400] = { id = 26400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Universal Key", description = "We're going to need something even stronger than those beefy {race} hands of yours to open this.  And the Venture Company schlubs to the northwest might have just the thing.\n\nLast time I was over there, I saw shredders walking around with giant rotating blades on their hands.  That's one way to open a box!\n\nIf you can't find any shredders, you might also try the giant sawblade in their lumber mill, by the lake.", sourceObjective = "Open the Mosh'Ogg Bounty by fighting a Venture Co. Shredder or by using the sawblade in the Venture Company lumber mill.", progress = "You get that chest open yet?  I can't wait to see what's inside.", completion = "<The goblin peers inside.>\n\nWhaaaaaa?!?\n\nI'm... I'm going to have to send this to... to Flem... in the south.  He'll know what to do with it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26401] = { id = 26401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Vestia", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. Is this what the apprentice was searching for?", sourceObjective = "Bring the Darkmist Amulet to Vestia Moonspear at the Tower of Estulan.", progress = "You're back... and without him...", completion = "How horrible... for someone so young and full of promise to fall to demons!\n\nI beg your forgiveness for sending you into danger as well, {name}. I hope you don't cross paths with that demoness again...", sourceObjectiveStatus = "unverified-source-field" }
quests[26402] = { id = 26402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Shandris Feathermoon", description = "We druids do not keep very close company with the Sentinel army, but we are always willing to work together to defend our lands. Now that you have assisted me, I would be remiss in not requesting you assist them as well.\n\nShandris Feathermoon, general of the Sentinels, commands the war effort for all of Kalimdor from the newly built Feathermoon Stronghold to the south. Tell her I sent you; I am sure she will have need of your skills.", sourceObjective = "Speak with Shandris Feathermoon at Feathermoon Stronghold in Feralas.", completion = "Telaron has already sent word of you, {name}. I'm interested in seeing if you're half as skilled as he claims.\n\nI am fighting a war on multiple fronts, while keeping our currently held areas properly defended, as well as overseeing the instruction of our youngest sentinels. If you're a decent fighter, there will be plenty for you to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26403] = { id = 26403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company Mining", description = "Man, I hate the Venture Company.  They have a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti to the northwest are deeply interested in those strange blue crystals they have been finding in the mines.  Bring me samples of the stone from their geologists.  I don't care what you have to do to get them.", sourceObjective = "Bring 5 Tumbled Crystals to Skeezy Whillzap at Bambala in Northern Stranglethorn.", progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26404] = { id = 26404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Above My Pay Grade", description = "Hey, have you been to Hardwrench Hideaway yet?  Oh, you've GOT to see it.  It's everything a goblin could ever hope for.\n\nTell you what... you look like a stand-up {class}.  Raskha in the vest and the skirt over here can give you a ride, if you don't already know the way.\n\nThe flight's on me.", sourceObjective = "Report to Sassy Hardwrench at Hardwrench Hideaway in the Cape of Stranglethorn.", completion = "Skeezy sent you to the right place.  Welcome to Hardwrench Hideaway!", sourceObjectiveStatus = "unverified-source-field" }
quests[26405] = { id = 26405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel south to Zul'Mamwe and cull their wayward tribe.", sourceObjective = "Kill 16 Skullsplitter Trolls within Zul'Mamwe.", completion = "As promised, your reward.  You do the troll nation proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[26406] = { id = 26406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn.  Their venom is strong, {name}... don't get careless.", sourceObjective = "Collect the Fang of Shadra from the Creeping Ruins.", progress = "Have you got the fang?", completion = "There it is... only one left.", sourceObjectiveStatus = "unverified-source-field" }
quests[26407] = { id = 26407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mosh'Ogg Handiwork", description = "This ogre was carrying an unusual item: the severed hand of another ogre, tied to a piece of string, and worn around the neck.  The hand itself is marked heavily with scars that glow a faint purple.\n\nA scar that glows after death is highly unusual, and to find such an item on an ogre is even stranger.  Perhaps someone back at Grom'gol will know what to do with this oddity.", sourceObjective = "Bring the Disfigured Mosh'Ogg Hand to Far Seer Mok'thardin at Grom'Gol Base Camp in Northern Stranglethorn.", progress = "A hand, you say?", completion = "<The Far Seer makes sure to hold the item by the string, carefully avoiding the dead ogre's fist.>\n\nStrange indeed.  I will pass this on to my contacts in the east, near the Mosh'Ogg's main camp.  I have a feeling that they'll be interested in these strange scars.\n\nYou have my thanks, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26408] = { id = 26408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes in Ashenvale", description = "Darkshore may be battered and broken, but thanks to you, we've achieved some amount of safety here. Some amount of peace. We've much rebuilding to do.\n\nYou should continue on, friend. Garrosh has pressed the full might of his Horde against us in Ashenvale. They will kill all of us and chop the forest clear if we don't step forward to stop them.\n\nIf we are to have any hope of not losing those forests entirely, we'll need your help. Follow the road to the south and find Sentinel Shyela.", sourceObjective = "Speak to Sentinel Shyela at Orendil's Retreat in Ashenvale.", completion = "Good to see a new face around here!\n\nThe forest crawls with Horde, but my assignment requires that I keep this outpost safe. I could really use someone who might be up for a good fight.", sourceObjectiveStatus = "unverified-source-field" }
quests[26409] = { id = 26409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Goldmine?", description = "My goblin initiate has been gone for quite some time. His name is Goldmine.\n\nI sent him out to observe the local rock flayers southwest at the Quartzite Basin. Perhaps you would be willing to find him? When you do, please ask him to come back to the temple.", sourceObjective = "Find Initiate Goldmine at the Quartzite Basin in Deepholm.", completion = "Hiya! Lend a hand, would ya, bub?", sourceObjectiveStatus = "unverified-source-field" }
quests[26410] = { id = 26410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Bonding Compound", description = "This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count!\n\nWe know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment?\n\nMy heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.", sourceObjective = "Collect 5 Quartzite Resin.", progress = "It won't take much resin. Those rock flayers are pretty dangerous though.", completion = "Good thing that I just happen to be a grand master of all things explosively alchemical.\n\nThis won't ignite on its own, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[26411] = { id = 26411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply and Flash Dry", description = "Alright, take this and apply it to his wounds. If the cauterizing effect of the flash dry explosion doesn't crack him wide open, it should completely heal him.\n\nI think.", sourceObjective = "Use the Explosive Bonding Compound on Flint Oremantle.", progress = "Don't yap at me. Use the explosive bonding compound on Flint.", completion = "Looks like that did it. He should come to any moment now.\n\nI told you I was a grand master of alchemy!\n\nI've got some extra resin leftover. I can make it into all kinds of explosively wonderful stuff. What do you want?", sourceObjectiveStatus = "unverified-source-field" }
quests[26412] = { id = 26412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that they're hiding some special, magical artifact in their cave.  Skeezy knows better, though.  I can smell money from a Mulgore mile away, and I'll bet that ogre doodad's worth a fortune.\n\nHere's a hint: I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", sourceObjective = "Obtain the Mosh'Ogg Bounty from the ruins behind the Mosh'Ogg Ogre Mound.", sourceObjectiveStatus = "unverified-source-field" }
quests[26413] = { id = 26413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Him to the Earthcaller", description = "He still looks a little loopy to me. His head must still be ringing.\n\nBest get him inside the temple and see what the Earthcaller wants to do with him.\n\nI think I'm going to stay out here a little while longer and \"observe\" these rock flayers.", sourceObjective = "Introduce Flint Oremantle to Earthcaller Yevaa at the Temple of Earth.", progress = "One of the Earthen? This is an unexpected and fortuitous surprise, {name}.", completion = "We are honored by Flint Oremantle's presence. I am given to understand that the Stonefather is in possession of a fragment of the World Pillar.\n\nIt is imperative that we recover all of the fragments. The instability between worlds is increasing. Soon it may become too great even for mighty Thrall to hold at bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[26414] = { id = 26414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hitting a Walleye", description = "Sometimes, I fish for fun.  Other times to relax, but sometimes I want a challenge.  That's where the hardened walleye comes into the picture.  This prized fish is not caught for us to eat, but for the challenge.  You can find the walleye in Stormwind Lake just north of the city.  Think you are up to the challenge?", sourceObjective = "Catherine Leland in Stormwind City wants you to bring her 8 Hardened Walleye.", progress = "Was the challenge too much for you?", completion = "Nice work {name}!  I see you are quite the fisherman these days.  Might just have to take you out on the boat soon and see what you can really do!", sourceObjectiveStatus = "unverified-source-field" }
quests[26416] = { id = 26416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well, Come to the Jungle", description = "My commander has sent me to scout for potential recruits to assist in the defense of Grom'gol Base Camp in Northern Stranglethorn.  Are you familiar with Stranglethorn?  It's a long way away... across the Great Sea, on the southern tip of the Eastern Kingdoms.  You fit the build he was looking for... interested in leaving Kalimdor for a while?\n\nIf so, then go talk to my cohort Bort in Orgrimmar.  He'll help you board the zeppelin.\n\nAnd tell him I said \"Woozle wozzle.\"  He'll know what it means.", sourceObjective = "Report to Bort in Orgrimmar.", completion = "Hah!  That Cromula cracks me up.\n\nOh, right, Stranglethorn.  You're really going?", sourceObjectiveStatus = "unverified-source-field" }
quests[26417] = { id = 26417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Stranglethorn: The Fallen Empire", description = "Commander Aggro'gosh is looking for devoted members of the Horde to assist him and his mission in Grom'gol.  If you're interested, just hop on up to the top of that zeppelin tower and board the Grom'gol zeppelin.  It's that easy!\n\nSeriously, Stranglethorn is the place to be right now... there's plenty of action to be found, and not nearly as much cataclysmic damage as, say... Stonetalon Mountains.  I wish I could go with you.", sourceObjective = "Report to Commander Aggro'gosh at Grom'gol Base Camp in Northern Stranglethorn.", completion = "Glad you could make it!  Let's get to work, shall we?", sourceObjectiveStatus = "unverified-source-field" }
quests[26418] = { id = 26418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shell of Shadra", description = "We've one last part to collect, and then we'll have everything we need.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nSimple enough, no? Get up the steps of the altar and send her head rolling back down them. Bring the shell to me and we will have Shadra at last.", sourceObjective = "Kill Qiaga the Keeper and collect the Shell of Shadra.", progress = "Do you have it?", completion = "Yes... it's finally time. Shadra will be ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[26419] = { id = 26419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra the Venom Queen", description = "<The ground rumbles as the idol sits on the altar, and the lake below roils! Shadra is emerging!>", sourceObjective = "Kill Shadra the Venom Queen.", completion = "Excellently done. You have served the Dark Lady well today, {name}.\n\nThis virulent blood will supply our armies with all manner of powerful weapons against the disgusting Alliance. We will wipe them from these lands.\n\nFor the Horde, of course... and all thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26420] = { id = 26420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diggin' For Worms", description = "Hey there, Angler!  Arnold here tells me that you have been looking for a new fishing spot and I think I know just the place.  North of Stormwind there is a great little spot called Olivia's Pond.\n\nThe pond is stocked with crystal bass every year but they are hard to catch.  They only bite on a very specific type of bait... overgrown earthworms.  If you search the shore around the pond, you should find plenty of worms to use as bait.", sourceObjective = "Find an Overgrown Earthworm near Olivia's Pond and use it as bait to catch a Crystal Bass. Crystal Bass can be found in Olivia's Pond, north of Stormwind.", progress = "Did the bait work?", completion = "Those look like some nice bass, {name}.  Let's fry 'em up and see how they taste!", sourceObjectiveStatus = "unverified-source-field" }
quests[26421] = { id = 26421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", sourceObjective = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26422] = { id = 26422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", sourceObjective = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26423] = { id = 26423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", sourceObjective = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26424] = { id = 26424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", sourceObjective = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26425] = { id = 26425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", sourceObjective = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown.", completion = "It's good to meet you, {name}. You've probably heard others speaking of Operation: Gnomeregan. Let me tell you a bit about what happened and why we left the dwarven city of Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[26426] = { id = 26426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Violent Gale", description = "There is a task that I can set before you.\n\nIt is a dangerous task. Completing it will help impress the more stubborn Stone Lords.\n\nTo the northwest is the Scoured Reach. Severe winds batter the rock and hide the true living threat underneath.\n\nWithin the Scoured Reach are Gyreworms. They devour rock and move through it as if it were water. They do the same thing to our rocky skin.\n\nFind Felsen the Enduring. Have him direct you to the Crumbling Depths. I will speak to you once you get that far.", sourceObjective = "Find Felsen the Enduring and follow his instruction towards the entrance to the Crumbling Depths.", completion = "<The ground rumbles slightly as you approach the cave. This looks to be the entrance that Diamant and Felsen spoke of.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26427] = { id = 26427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without a Captain or Crew", description = "Not sure who you're with, but you don't look like one of... them.\n\nI'm not sure what happened.  I slept through supper and woke up to a ship full of dead people and murderers.\n\nNot sure if you want to kill me or not, but I'll spare you the trouble.\n\n<Moody points to a wound in his stomach.  His insides are not where they should be.>\n\nI can keep steering the ship for a while longer.  You don't die from a gut wound immediately.  Just bring me some rope and some rum... no, whiskey.", sourceObjective = "Bring First Mate Moody a Bottle of Whiskey and a Spool of Rope.", progress = "You have what I asked for?", completion = "All right, help me get tied to the wheel.\n\n<Moody sips from the bottle.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26428] = { id = 26428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, she and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", sourceObjective = "Take the heads of Kenata Dabyrie, Fardel Dabyrie, and Marcel Dabyrie.", progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off.", sourceObjectiveStatus = "unverified-source-field" }
quests[26429] = { id = 26429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush the Witherbark", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", sourceObjective = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors.", completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26430] = { id = 26430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revantusk Village", description = "Not all forest trolls are foul nuisances like the Witherbark. North of here in the Hinterlands is Revantusk Village, home to the only forest troll tribe still allied with the Horde.\n\nEven they cannot escape the cruelty of their bretheren. The Vilebranch tribe wars with them, distracting them from our battle with the Alliance.\n\nYou have fought well here. Speak with Urda if you wish to fly to Revantusk. Their village will have use of your strength.", sourceObjective = "Travel to Revantusk Village in The Hinterlands and speak with Elder Torntusk.", completion = "Welcome to Revantusk, {class}. I hope fighting the Witherbark hasn't exhausted you; the Vilebranch are even worse.", sourceObjectiveStatus = "unverified-source-field" }
quests[26431] = { id = 26431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archaeology", description = "Accept this quest to find archaeology points on your map!" }
quests[26432] = { id = 26432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Jintha'Alor", description = "We've got more to deal with than just dwarves, mon. While I watch the village, my mate Primal Torntusk has gone to lead our warriors against the wicked Vilebranch tribe.\n\nThey've killed our brothers, and I was even taken prisoner by them once. No more! This time, the city of Jintha'Alor falls to us.\n\nGo to Jintha'Alor and speak with my mate. She's captured a camp near the entrance to the city.", sourceObjective = "Find Primal Torntusk at Jintha'Alor in The Hinterlands.", completion = "Welcome, {class}. We're gonna make the Vilebranch regret ever crossin' us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26433] = { id = 26433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Holy Water of Clarity", description = "Skeezy said you'd be coming.  Let's identify this... thing.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  The nagas to our southeast maintain a hallowed shrine that dispenses a water so clean, so fresh, and so mouthwateringly pure, that when the imbiber quaffs but a mouthful of the sacred stuff, their mind is cleansed and their best path made clear.\n\nSounds good, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", sourceObjective = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Flem's ears perk up as you approach.>\n\nThe Holy Water of Clarity?  Is it here!?", completion = "<The goblin downs the water in one gulp.>\n\nAhh... do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nOh, right... your artifact, and clarity.  Clarity...\n\nI've got it!", sourceObjectiveStatus = "unverified-source-field" }
quests[26434] = { id = 26434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Reagents of Power", description = "I see clearly now... the key to identifying this mysterious talisman revolves around obtaining some rare and precious items.  These Primal Reagents of Power, when properly combined, will reveal to us the origin of our treasure.\n\nTravel north, to the western side of the Gurubashi Arena, and hunt the cats that roam the jungle.  Their fleecy furs will lead us to the truth!", sourceObjective = "Obtain 4 Supple Tiger Furs and 4 Velvety Panther Furs.", progress = "Make sure the reagents are extra-cushy, {name}.  A scratchy reagent simply won't do.", completion = "<Flem feels the hides and smiles to himself.>\n\nExcellent work, {name}!  These reagents will serve perfectly.", sourceObjectiveStatus = "unverified-source-field" }
quests[26435] = { id = 26435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm A Huge Liar and a Fraud", description = "I have no idea what this artifact is.  I have no idea where I would even START finding out what it is.\n\nIn fact, I have no idea why anybody expected ME to be able to identify it in the first place.\n\nI asked for water because I was thirsty.  I asked for the jewelry and furs for... well, they're for my girlfriend.\n\nHopefully I can at least point you in the right direction.  Garley Lightrider in Booty Bay is a member of the Reliquary, and might be of more use than me.\n\nSorry.", sourceObjective = "Bring the Opened Mosh'ogg Bounty to Garley Lightrider at Booty Bay in the Cape of Stranglethorn.", progress = "Yes, {race}?  I'm quite busy.", completion = "Fascinating!\n\nI'll need some time to study this.  Why don't you have a look around Booty Bay and come back later?", sourceObjectiveStatus = "unverified-source-field" }
quests[26436] = { id = 26436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entrenched", description = "Your intentions appear true.\n\nI will impress upon the other Stone Lords my wary trust.\n\nWith this, they should speak to you.\n\nMore importantly, they should listen.\n\nEarning their favor may take time. Earning the Stonemother's favor may take more time. Time is a potent offering, so be generous with it.\n\nAmong the Shuddering Spires far to the northwest, you shall find Kor the Immovable. He is evenly tempered. His situation lends itself well to seeking outside aid.\n\nGo to him.", sourceObjective = "Seek out Kor the Immovable among the Shuddering Spires.", completion = "Diamant says you are to be trusted. Diamant is patient and wise, so I shall allow you to prove yourself.\n\nAs it happens, I could use hands that are more... mobile.", sourceObjectiveStatus = "unverified-source-field" }
quests[26437] = { id = 26437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Things Crystal Clear", description = "Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us.\n\nI do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself.\n\nBring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.", sourceObjective = "Collect 8 Chalky Crystal Formations.", progress = "Have you done this favor that I asked of you? Did you bring the crystals?", completion = "Ahh... invigorating. Thank you, fleshling.", sourceObjectiveStatus = "unverified-source-field" }
quests[26438] = { id = 26438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intervention", description = "The flayers have gone crazy with hunger. Their digging was once tempered and moderate. Now their hunger cannot be quenched. They grow murderously violent.\n\nThe flayers have turned on my sons. They overwhelm them. Kill them. It must stop.\n\nKill the flayers. They serve no purpose to the earth. Their passing will not be missed. Save my sons. Slaughter any flayers you find.", sourceObjective = "Kill 12 Jaspertip rockflayers.", completion = "You've proven useful, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26439] = { id = 26439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Pieces Together", description = "{race}. If you act in the service of the Stone Lords, there are those that might aid you.\n\nWatch for the Stonebound. They lie dormant all around the Shuddering Spires. It should not take much prompting to rebind them to service against the flayers.", sourceObjective = "Aid 6 Dormant Stonebound Elementals in reforming.", progress = "<Berracite grumbles, and you feel the reverberations gradually roll by under your feet.>", completion = "Thank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26440] = { id = 26440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clingy", description = "<A miniscule elemental seems to have taken a liking to you.>\n\nCaris... carstr... crystal? <Pebble looks up at you expectantly.>\n\n<You did notice a very large crystal formation towards the middle of the Shuddering Spires. Perhaps you should take him there?>", sourceObjective = "Bring Pebble to the large crystal formation in the Shuddering Spires.", progress = "<Pebble looks up at you expectantly.>", completion = "<The stones in Pebble's body bounce up and down happily. He seems very appreciative.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26441] = { id = 26441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So Big, So Round...", description = "<Pebble looks around, excited by something. After a few seconds of confusion, he stops and stares up at you with big, glowy gem eyes.>\n\nHug-nery... hungry...\n\n<Try as you might, there's no resisting those eyes. Maybe Kor knows what mini-mentals like to eat?>", sourceObjective = "Speak to Kor to find out what kind of food Pebble might like.", completion = "You've made a friend, have you?\n\nAre you certain you want to feed him? He might become attached.", sourceObjectiveStatus = "unverified-source-field" }
quests[26442] = { id = 26442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Lobster", description = "If I could choose my last meal, it would definitely be fresh lobster tail.  Something about that tasty crustacean is just irresistible!  We recently started trapping lobsters here in Stormwind.  Would you mind heading out and checking the traps for me?\n\nOne more thing, watch out for the sharks.  They can be vicious down there.", sourceObjective = "Collect 6 Rock Lobsters from the cages below the docks in Stormwind Harbor. Watch out for sharks!", progress = "Looks like you were able to avoid the sharks.  Were there any lobsters in the traps?", completion = "Looks like the traps are working!  Thanks {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26443] = { id = 26443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north, the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at the Warsong Lumber Camp would be interested in these?", sourceObjective = "Deliver the Diabolical Plans to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.", progress = "What do you have there, sir?", completion = "By the Seven Crystals of Ata'mal, this cannot be! They plan to attack Forest Song?!\n\nNot on my watch!\n\n<Vindicator Vedaar crumples the demon-scrawled plans in his fist.>\n\nNo. We will not allow this to happen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26444] = { id = 26444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "I will not tolerate their existence on this world! The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world. Then they came again and we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south and west in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge. They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", sourceObjective = "Slay any 15 demons at Felfire Hill, Demon Fall Canyon, and Demon Fall Ridge.", completion = "You have my respect and thanks, {class}. Perhaps we'll be able to create a new home here without having to worry about the Burning Legion yet again.", sourceObjectiveStatus = "unverified-source-field" }
quests[26445] = { id = 26445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders.  Without them the demons will be mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge. To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.\n\nBring me their weapons.", sourceObjective = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", progress = "Our night elf scouts report that preparations for the attack are almost complete. Those dreadlords must die soon, {name}!", completion = "Never again will the Burning Legion threaten Ashenvale! You have delivered us from a fight we very likely would have lost, {class}.\n\nI give you thanks, {name}, and the deepest gratitude of the Hand of Argus. It honors me to have you at our side!", sourceObjectiveStatus = "unverified-source-field" }
quests[26446] = { id = 26446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Felfire Hill", description = "Little one, to the southwest is an area of Nightsong Woods that has in recent times come to be called Felfire Hill. It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose. Take them to Felfire Hill and plant them in the fertile dirt mounds.", sourceObjective = "Plant 8 Tree Seedlings in the Fertile Dirt Mounds.", progress = "Surely you have not yet planted all of my seeds?", completion = "Good. Though it may take a great deal of your years for the seedlings to grow into ancients, in the fullness of time they will aid us in our fight against all of the enemies of Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[26447] = { id = 26447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", sourceObjective = "Deliver the Diabolical Plans to Valusha at Splintertree Post in Ashenvale.", progress = "What do you have there, scout?", completion = "Dreadlords!  They plan to attack us here at Splintertree Post?!\n\nNot while I still draw breath!\n\n<Valusha crumples the demon-scrawled plans in her fist.>\n\nNo.  We will not allow this to happen!  They are a blight upon our world!", sourceObjectiveStatus = "unverified-source-field" }
quests[26448] = { id = 26448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been a thorn in our side for far too long!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", sourceObjective = "Slay 15 of any demon type at Felfire Hill, Demon Fall Canyon, or Demon Fall Ridge.", completion = "That's better!  There's nothing quite like ridding our world of a demon.  And they make for worthy opponents as well, unlike the weak races of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[26449] = { id = 26449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Again!", description = "{name}, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.\n\nReturn to me with their weapons as proof of your deeds.", sourceObjective = "Obtain Gorgannon's Flaming Blade and the Seeker's Fel Spear.", progress = "Those dreadlords must die soon, {name}!", completion = "Never again will the Burning Legion make slaves of the orcs, or any other race of the Horde!\n\nBravely fought, {class}!  You have the true heart of the Horde beating inside of you!  You give us much honor!", sourceObjectiveStatus = "unverified-source-field" }
quests[26450] = { id = 26450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They're Just Going to Leave Them Lying Around...", description = "I was just thinking about something, {name}.  Those naga have more than just reeds down there.  They tend to keep little statues lying around on their shrines, in the sand, under their trees.  They don't seem to be USING them.\n\nI could use those statues!  I could... put 'em around the camp, make it feel a little more homey.  Anything's better than a bloody dinosaur corpsepump.  I could sell them as souvenirs.\n\nI could sell them back to the naga!\n\nWhy don't you go grab a couple while I figure this out.", sourceObjective = "Obtain 6 Naga Icons from the Southern Savage Coast in the Cape of Stranglethorn.", progress = "Let's see 'em!", completion = "Nice work, {name}.  Now I've just got to decide what to do with all of these...", sourceObjectiveStatus = "unverified-source-field" }
quests[26451] = { id = 26451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Challenge: Free-For-All Arena Combat", description = "The arena is a place of battle unlike any other.  Inside, you have no friends.  Alliances that do form are fleeting, as your allies can turn on you in the blink of an eye.  Horde vs. Alliance, Alliance vs. Alliance, Horde vs. Horde... anything goes.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", sourceObjective = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger.", progress = "Why don't you get a little bit more blood on your armor before you speak with me again?", completion = "Well done, {race}!  Did you feel it?  The rush of the melee?  The true risk of free-for-all combat?\n\nAs today is your first day here, I'll let you perform in one more competition for another reward.  If you return in the future, you may compete again, once a day.  Your rewards will, of course, improve as you become stronger.", sourceObjectiveStatus = "unverified-source-field" }
quests[26452] = { id = 26452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashi Challenge", description = "You've returned, {race}.  That means you've felt the call of the arena once more.  Very well.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", sourceObjective = "Place the Gurubashi Challenge Flag down inside the Battle Ring, then defeat the Gurubashi Arena Challenger.", progress = "Why don't you get a little bit more blood on your armor before you speak with me again?", completion = "Well done, {race}!  I look forward to seeing you fight again soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26453] = { id = 26453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Helping Hand", description = "Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, {name}, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested <men/women> his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", sourceObjective = "Speak with Architect Nemos at Forest Song in Ashenvale.\n\nVindicator Palanaar can offer you a ride to get you there more swiftly.", completion = "It's good to see another new arrival here at Forest Song.\n\nVindicator Palanaar is sending as much help as she can muster and each set of hands is appreciated.\n\nTake a look around, {class}. It may not be much now, but with time and help from our night elf allies, we'll build a settlement worthy of calling home. There is much to be done here and any help you can provide would be welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[26454] = { id = 26454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shameful Waste", description = "Welcome to Forest Song, {class}. Where you see tents, there will one day be buildings, but such ambition requires a steady stream of materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the west have no such reverence for the forest.\n\nWe shall reclaim the tainted wood from Satyrnaar to the west. Take the wood to Gnarl at the Warsong Lumber Camp. He is an Ancient who will purify it for our use.", sourceObjective = "Collect 5 Satyrnaar Fel Wood.", progress = "<The ancient creaks as it turns toward you.>\n\nArchitect Nemos said that you might be bringing wood salvaged from befouled Satyrnaar.", completion = "Wood warped by foul demonic magic is of no use to the draenei at Forest Song. Nothing sound can be built with it, but I shall purify it and return it in good time to Architect Nemos and his people for their use.\n\nSome good will come from this tragedy, after all.", sourceObjectiveStatus = "unverified-source-field" }
quests[26455] = { id = 26455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, {name}.", sourceObjective = "Obtain the Chalice of Elune.", progress = "Can you feel it, {name}, the touch of corruption upon the wind? If we do nothing, it will continue to advance. That is why I seek the Chalice of Elune. Were you able to find it?", completion = "Excellent work, {name}. There is certainly a latent power here, one that not even constant exposure to the corruption of the satyr can dim.\n\nDo you see how it still shines, after all these years?", sourceObjectiveStatus = "unverified-source-field" }
quests[26456] = { id = 26456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report from the Northern Front", description = "The battle against the Horde isn't being waged from Raynewood Tower alone, {name}. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southeast, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to her, but also hesitant to leave the tower unattended.\n\nI am in dire need of your help in getting this report to her as soon as possible!", sourceObjective = "Deliver Sentinel Melyria's report to Sentinel Farsong at Silverwing Grove in Ashenvale.", progress = "What's that you have there, {class}?", completion = "Thank you for delivering this report, {class}. From what Sentinel Melyria writes, it seems our worst fears have come to pass. With each advance we make, the Horde appears more determined to do as much damage as possible.\n\nWe can't afford to back down; the fate of our ancestral lands hangs in the balance. With more people like you on the frontlines, I'm certain we could triumph.\n\nWill you join our fight? A new front has just opened in Warsong Gulch to the south.", sourceObjectiveStatus = "unverified-source-field" }
quests[26457] = { id = 26457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, {name}, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", sourceObjective = "Slay Overseer Gorthak and any other 12 Horde at the Warsong Lumber Camp.", completion = "At last we have sent a message that the orcs won't dare ignore. Any overseer or foreman who sets foot within the camp to replace Gorthak will feel my wrath!\n\nWe must press our advantage, {name}, and never rest until the Warsong Lumber Camp is a distant memory and a glade of trees stands upon that ground.\n\nNow what was this about explosives...?", sourceObjectiveStatus = "unverified-source-field" }
quests[26462] = { id = 26462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wicked Revantusk", description = "These Revantusk trolls think they're special for bein' in the Horde. Makes me laugh!\n\nSee, the funny part is, it doesn't matter if they're part of the Horde, or some kinda troll empire, or the bloody Burning Legion for that matter. We've fought trolls in these lands for a few centuries now.\n\nIn fact, I'll be kind enough to let you lend a hand, <lad/lass>! Grab a weapon and head out to the battlefield and help our boys to the east.", sourceObjective = "Kill 10 Revantusk Stalkers or Revantusk Hexxers.", completion = "Not bad for a city-dwellin' {race}. Good show, aye!", sourceObjectiveStatus = "unverified-source-field" }
quests[26463] = { id = 26463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding Teronis", description = "A friend of mine from Astranaar, Raene Wolfrunner, asked me to send a scout west to Lake Falathim. Teronis left days ago, just before the Horde attacked.\n\nHe was searching for an item he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left, he mentioned a gem for the rod. Unfortunately, we know that the lake has been invaded by some evil force.\n\nPlease, {name}, find my friend.", sourceObjective = "Find Teronis at Lake Falathim in Ashenvale.", completion = "Teronis' body lies broken atop the small rise next to the Keeper.\n\nDeep slashes crisscross his corpse.", sourceObjectiveStatus = "unverified-source-field" }
quests[26464] = { id = 26464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Gem", description = "As you rummage through Teronis' belongings, you find a water-damaged journal.\n\nQuickly flipping through the last legible pages, you read that Teronis makes mention of finding the gem, but then of having lost it in the Falathim area.\n\nThe only thing left to do is find it. Perhaps the tendrils have it...?", sourceObjective = "Find the Glowing Gem.", progress = "Ah, welcome back, {name}.", completion = "This is terrible, {name}. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I will send some of the Sentinels to recover Teronis' body and to assist the keeper.\n\nYou have the gem that Teronis was seeking? It must be delivered to Astranaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26465] = { id = 26465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ancient Statuettes", description = "I would charge you with a task, {class}.\n\nI was on my boat, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws! I fled and the rest, as they say, is history.\n\nI am an archaeologist of sorts, and I am attempting to recover artifacts of the lost city.\n\nWill you head out onto the Zoram Strand to the southwest and recover any ancient statuettes you come across? They are the reason I have braved the dangers of the Zoram Strand.", sourceObjective = "Collect 10 Ancient Statuettes.", progress = "Have you found many statuettes, {name}?", completion = "That's quite a few that you have found! Thank you, {name}!\n\nThe old city of Zoram holds many secrets, and these statuettes may be the key to many of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[26466] = { id = 26466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuzel", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to their ancient locks.\n\nThat key is a ring, the Ring of Zoram. It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on her isle on the northern edge of the Zoram Strand. Please, {name}, retrieve the ring for me!", sourceObjective = "Obtain the Ring of Zoram.", progress = "It is said that the Ring of Zoram is the key to any lock within the city. Do you have it, {name}?", completion = "You found the ring! Thank you, {name}.\n\nPlease take this as payment, and know that your deeds today will remain forever in my memory.", sourceObjectiveStatus = "unverified-source-field" }
quests[26467] = { id = 26467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Satyr! Dryads in Danger!", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n{name}, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", sourceObjective = "Find Anilia at Xavian in Ashenvale.", completion = "Judging by the gaping wound in her side, Anilia is on the verge of death.", sourceObjectiveStatus = "unverified-source-field" }
quests[26468] = { id = 26468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Branch of Cenarius", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", sourceObjective = "Obtain the Branch of Cenarius.", progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over...", sourceObjectiveStatus = "unverified-source-field" }
quests[26469] = { id = 26469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Slaying!", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", sourceObjective = "Obtain 16 Satyr Horns.", progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind {race}. My sister's spirit is gladdened by your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[26470] = { id = 26470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaking Mystral Lake", description = "We could easily have held Silverwind Refuge from the Horde had they not taken control of our water elemental defenders on Mystral Lake.\n\nOne of their shaman summoned in Tideress, an old and angry water spirit of the forest who befouled our elementals and turned them against us. With the lake and the Horde pressing in on us, we had no choice but to retreat to the spire here.\n\nGo east. Take the lake back so that we will have a chance to retake the refuge some day.", sourceObjective = "Slay 12 Befouled Water Elementals and Tideress.", completion = "Well done, {name}! With the befouled elemental numbers thinned and Tideress put back into the lake, we should be able to launch a counter-offensive on Silverwind Refuge.\n\n\n\nJust as soon as we're done with defending the spire....", sourceObjectiveStatus = "unverified-source-field" }
quests[26472] = { id = 26472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insane Druids", description = "The druids are dead, killed by their leaders who were driven insane by the Horde tainting the Forest Heart! I can feel the corruption even from here and I dare go no further.\n\nWhile I am too well attuned to Ashenvale and the Forest Heart, you... you could descend into the barrow den and do what must be done. I've laid down breadcrumbs for you in there.\n\nThough it tears me apart, I must ask that you put to rest the druids' once great leaders: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", sourceObjective = "Slay the insane druids: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", completion = "Rest in peace, my friends.\n\n<You can see the sorrow in the druid cat's eyes.>\n\nI felt the anguish of the Dor'danil Barrows lessen, and knew that you had completed your task.\n\nIt was grim work that you did, {name}, for the spirits you destroyed were merely victims of the Horde's evil. But with their destruction, let us hope the maddened spirits will finally find peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[26473] = { id = 26473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bathran's Hair", description = "There is a plant that grows in the old ruins of Bathran's Haunt across the road to the east. The plant is called Bathran's Hair and is known to cure ailments of the spirit.\n\nNow the Horde are there harvesting the plant for their own evil schemes.\n\nThere is a sick child in Astranaar, and we believe that her illness is more than just physical. I promised my master that I would help seek a cure, but I am no fighter.\n\nWill you go to Bathran's Haunt and gather the plants?", sourceObjective = "Collect 8 Bathran's Hair.", progress = "Have you gathered the Bathran's Hair, {name}?  The child's health grows weaker by the hour....", completion = "Ah, you have the hair! This is a good first step. There are other ingredients that we will need, but the hair of the fallen Ancient could well be the most important.\n\nI only hope that whatever the Forsaken are devising from the plant will not be turned into a weapon. We simply do not have the numbers to remove them right now, especially with Maestra's Post under attack!", sourceObjectiveStatus = "unverified-source-field" }
quests[26474] = { id = 26474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orendil's Cure", description = "{name}, now that it has been bathed in Elune's blessed light, I believe that the concoction will help the afflicted child. Please, take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south and then east. However, if you'd like to get there more swiftly, speak with Sentinel Avana.", sourceObjective = "Bring Orendil's Cure to Pelturas Whitemoon at Astranaar in Ashenvale.", progress = "I must apologize, for I have no time to speak. My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great! This cure gives me hope, when before I had little....", sourceObjectiveStatus = "unverified-source-field" }
quests[26475] = { id = 26475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Tear", description = "I'd hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through her. We must find more powerful medicine! Thankfully, Orendil spoke to me of further remedies should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the remains of Iris Lake, destroyed by the eruption of Thunder Peak, northeast of Astranaar. Orendil said the stone will wash away corruption.\n\nPlease, {name}, bring me Elune's Tear and pray it will end my child's sickness!", sourceObjective = "Collect Elune's Tear.", progress = "{name}, did you find the remains of the lake?  Do you have the Tear?", completion = "Oh, you found it! Odd... it looks tarnished somehow. I will place the tear in a stew, and pray that it will cure her.\n\nThank you! Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26476] = { id = 26476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryad Delivery", description = "Ah, there you are, {name}. I've pored over the notes Teronis has made and it sounds like your next course of action is to find the other pieces of Dartol's rod.\n\nI would start by heading east along the road to Raynewood Tower.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", sourceObjective = "Deliver the Glowing Gem to Shael'dryn at Raynewood Tower in Ashenvale.", progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed.\n\nWhat can I help you with?", sourceObjectiveStatus = "unverified-source-field" }
quests[26477] = { id = 26477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search the Bole", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nTo find the next piece of the rod, you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here near the Felwood border, at the Howling Vale. Once you have it, look for a small glade through the tunnel at the vale. The chest should be hidden around there.", sourceObjective = "Find the Wooden Key and use it to obtain the Iron Shaft portion of Dartol's Rod.", progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26478] = { id = 26478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playing Possum", description = "The last piece of the rod is held by druids of the claw. I asked their leader, Oso Bramblescar, to give it to me, but he and his guardians nearly killed me! Clearly they too were affected by the Horde's corruption of the Forest Heart.\n\nBut, I have an idea for how you can get into Oso's cave and grab the pommel.\n\nEver since I was a faun, I've been pretty good at playing possum. It works great against bears! I can teach you! Go east to the Shady Nook, and if they try to get you, just use my technique.", sourceObjective = "Obtain the final piece of Dartol's Rod, the Iron Pommel.", progress = "Did you find the final piece of the rod, {name}? How did my technique work?", completion = "You got it? Wonderful for you... and for Raene!\n\nI guess we'll have to see about reassembling it, won't we?", sourceObjectiveStatus = "unverified-source-field" }
quests[26479] = { id = 26479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Raene", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nBe careful... I sense a great deal of power within it for both good and ill. I hope that you and Raene know what you are doing.\n\nGood luck, {name}.", sourceObjective = "Deliver Dartol's Rod to Raene Wolfrunner at Astranaar in Ashenvale.", progress = "Yes, {name}? How go your efforts?", completion = "You've recreated the rod Teronis had set out to find? That's wonderful to hear.\n\nShael'dryn has been indispensible in her assistance. Teronis would be proud to see his quest is continuing even after his tragic passing.\n\n<Raene looks over the reconstructed rod with a look of approval and thoughts racing behind her eyes.>\n\nNow it is time for us to make use of its power to eliminate the enemies of Ashenvale!", sourceObjectiveStatus = "unverified-source-field" }
quests[26480] = { id = 26480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dartol's Rod", description = "I'm not completely certain what Teronis had in mind next, but if what he said was true about the rod's power, then it will allow you to take on another form altogether, presumably that of a furbolg.\n\nPerhaps he meant to use its powers to get closer to them, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was uncorrupted.\n\nI would start with one known as Krolg. Seek his hut southeast of Mystral Lake.", sourceObjective = "Use Dartol's Rod to be able to communicate with Krolg at Krolg's Hut in Ashenvale.\n\nProvided item:", completion = "Yes, yes... you appear as one of my kind, but I care not what you truly are if you can help the furbolg.\n\nThe night elves and now the orcs have visited many atrocities upon my people.\n\nCorruption runs through our veins, corruption brought down upon us by the prideful night elves and the warlike orcs. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.\n\nAt night I can still see the campfires burning in the darkness.", sourceObjectiveStatus = "unverified-source-field" }
quests[26481] = { id = 26481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Adornment", description = "I'm certain that the long-dead wizard, Dartol, intended to use his rod to subjugate and destroy us just as the night elves and orcs have, but I think now we'll put that thing to an unintended use.\n\nRan Bloodtooth is the king of all of the Ashenvale furbolg. His tribe, the Bloodtooth, are the most powerful and keep themselves secluded in a camp just to the east.\n\nKill them all and bring back his skull. Let us see if we can put it to good use.", sourceObjective = "Obtain Ran Bloodtooth's Skull and Dartol's Rod.", progress = "Have you slain Ran yet, my friend? We must have his skull if you're to deliver my people from bondage.", completion = "You have done well, my friend.\n\nNow quickly, hand me Ran's skull. While his essence yet taints it, we shall fashion it upon Dartol's Rod giving you the power to influence my brethren and deliver them from evil!", sourceObjectiveStatus = "unverified-source-field" }
quests[26482] = { id = 26482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Power of the Rod", description = "Now, take the rod and while using its power, speak with my brother, Ota Wen.\n\nOta is amongst the other furbolg that the orcs have captured and have penned in the giant cage on the north side of Silverwind Refuge. The rod will allow you to convince Ota and the other furbolg to rise up and attack the Horde.\n\nThen you may go wherever your path leads you. Just know that you have found a new friend for that which you have done.", sourceObjective = "Use Dartol's Rod and speak with Ota Wen. Convince him to rise up against his Horde oppressors. Then, deliver Dartol's Rod to Raene Wolfrunner.", progress = "You return, {name}. What's that affixed to the top of the rod? A skull?", completion = "So, you used the skull of the furbolg king to modify the power of Dartol's Rod? You then used that power to convince the captured furbolg to rise up and attack the Horde at Silverwind Refuge?\n\nI am more than pleased and impressed with your abilities, {name}. The Sentinels cannot thank you enough. It should be a simple matter for us to sweep away the orcs and retake the refuge now!\n\nTeronis would be proud. You have my deepest respect.", sourceObjectiveStatus = "unverified-source-field" }
quests[26483] = { id = 26483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'dranda", description = "As fun as it is to butt heads with these trolls, we've got other things to do down here. It'd be nice to get this battle over with, aye?\n\nTheir commander, Gan'dranda, sits in the ruined walls to the southeast of the battlefield. Our boys have most of their forces locked up, so I want you to slip in there and take out Gan'dranda. When they see a {race} standin' over the corpse of their biggest hero it should take some of the fight out of 'em!", sourceObjective = "Kill Gan'dranda.", completion = "Now that's what I like to hear! Good on ya.", sourceObjectiveStatus = "unverified-source-field" }
quests[26484] = { id = 26484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stonehearth's Aid", description = "The earthen and the stone troggs somehow found their way to Deepholm through Uldum more than fifteen thousand years ago. They've been warring ever since.\n\nIf we're to recover the middle fragment of the World Pillar, the Stonefather must be rescued.\n\nPlease go to Stonehearth and do everything that you can to aid the Earthen in their war against the stone troggs.\n\nYou're our best hope, {name}.", sourceObjective = "Speak with Crag Rockcrusher at Stonehearth in Deepholm.", completion = "The Stonefather's son, Flint, sent you? No time to talk.\n\nWe must prevent a second front from opening up on the war!", sourceObjectiveStatus = "unverified-source-field" }
quests[26485] = { id = 26485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snapjaws, Lad!", description = "I've got plans to brew up somethin' special for those pesky trolls. Aye, I said for them... a brew they won't ever forget! A brew that'll have them pickin' their tusks out of the hillsides!\n\nI've got a few ingredients steepin' already, but I could use a hand gatherin' more. At the bottom of the Overlook Cliffs to the east, near the shore, is a whole mess o' snapjaws. I need fresh, whole gizzards from them for my blastbrew.", sourceObjective = "Collect 8 Snapjaw Gizzards from Saltwater Snapjaws.", progress = "Got those gizzards?", completion = "Ah, nice an' fresh. I'll get those going while you fetch me some more goods then...", sourceObjectiveStatus = "unverified-source-field" }
quests[26486] = { id = 26486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "99 Bottles of Booze on the Beach", description = "Now, I know we've got a little battle ragin' and all that, but down at the overlook cliffs are some nice lookin' bottles strewn all over the place. I don't want good drink to fall into the hands o' the Horde!\n\nIf you're down that way, collect the bottles for me and bring 'em back here. I'll pay in full for it as if you bottled 'em yourself.", sourceObjective = "Collect 12 bottles of Pupellyverbos Port.", progress = "About 12 should do the trick, aye?", completion = "That's the stuff! Wouldn't want any trolls or goblins gettin' pleasure out of these, now would we!\n\nMaybe I can work a bit of this into my next brew...", sourceObjectiveStatus = "unverified-source-field" }
quests[26487] = { id = 26487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akiris by the Bundle", description = "It's not easy running a combination 5-star exotic resort/jungle resource salvaging plant!  That is, it wouldn't be easy, if I didn't have the organizational skills of a trade prince's personal assistant!\n\nThe first trick is multitasking.  For example: the naga explorers to our south carry a valuable ocean reed - Akiris reeds.  We can sell these reeds to our clients overseas, and we can also stuff our visitors' mattresses with them!  Come to think of it, we could probably use some more of that stuff.", sourceObjective = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Let's see... we're going to need some shotguns for our nature hikes, rowboats for the oil rig day trip, and...\n\nOh, you're back already?", completion = "Hey hey!  Not bad, not bad at all!  You may have a future in resource acquisition.  Or hotel management.", sourceObjectiveStatus = "unverified-source-field" }
quests[26488] = { id = 26488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Big Gulp", description = "Arnold and I used to relax down at the moat in the Valley of Heroes.  One day, I lost my locket in the lake and I have never been able to find it.  Rumor has it that huge royal monkfish live in that moat and that they eat anything!  I know it's a long shot, but do you think you could catch a few monkfish and look for my locket?\n\nPlease let me know right away if you find it, it's very precious to me.", sourceObjective = "Fish up a Royal Monkfish from the moat in the Valley of Heroes district of Stormwind. Once you catch a monkfish, fillet it and check if it swallowed the locket.", progress = "Were you able to find my locket?", completion = "You found it!  I can't believe it was down there all those years!  You have no idea how much this means to me {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26489] = { id = 26489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's You!!", description = "Yes, can I help...\n\n<Sassy's jaw drops to the floor.>\n\n{name}!  Is it really you?!  Look how big and strong you've gotten!  Let me feel that bicep!\n\nMe?  I've been trying to make my gold here in the jungle.  We're mainly in resource acquisition, but we also do tourism.\n\nI know, genius, right?\n\nHey, listen.  I was thinking... the naga explorers to the south carry Akiris reeds, which we could sell, and use to stuff visitor mattresses.  You interested in killing some naga?  It'll be just like old times!", sourceObjective = "Obtain 6 Akiris Reeds from Naga Explorers.", progress = "Let's see... we're going to need some shotguns for our nature hikes, rowboats for the oil rig day trip, and...\n\nOh, hey Boss {name}.  You're back already?", completion = "I knew you had it in you, boss-lady.  You know what they say: You can take the {race} out of the islands, but you can't take the murderous tendencies out of {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26490] = { id = 26490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prime Slime", description = "Not many dwarves know this, but to get a REAL kick out of my brew I add a wee bit of the oozes around here. Aye, the giant green dwarf-eatin' oozes, those ones.\n\nThis brew's gonna have a HUGE kick to it though, so we need a huge slime! There's one lurkin' down in Skulk Rock that's the mother o' them all, absolutely huge...the Direglob, we call it.\n\nIf you've got what it takes, head down there and take a chunk out of the Direglob for me!", sourceObjective = "Collect a Direglob Sample from The Direglob.", progress = "Aye, do ya have it?", completion = "Look at it! That'll put some oomph into the mix!", sourceObjectiveStatus = "unverified-source-field" }
quests[26491] = { id = 26491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth takin' for our allies!\n\nProblem is, it's full of dwarf-eating slimes and oozes. Those things are slightly less disgustin' than trolls, but they'll still give us a hassle.\n\nWith our boys tied up fightin' the Revantusk, I need you to go to Skulk Rock and clear the place out for me.", sourceObjective = "Kill 10 Jade Oozes.", completion = "It's good to see you back... and not missing any limbs, either.", sourceObjectiveStatus = "unverified-source-field" }
quests[26492] = { id = 26492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulk Rock Supplies", description = "I had a cousin in the second war! He used to tell me all about when they led a raid on Skulk Rock. Swept in there and drove the trolls out like rats from a nest. They chased right after 'em all the way to Alterac!\n\nThe slimes moved in right quick after that, and there's still cratefuls of old Horde goods sittin' in there. I say we don't let the trolls get it back!\n\nBring me back a few crates from Skulk Rock to the northwest.", sourceObjective = "Collect 5 Ooze-Coated Supply Crates.", progress = "You got the crates?", completion = "Looks like it's still good inside! Huh... is that banana bread? Still fresh!\n\nHere, lad, take your share of goods.", sourceObjectiveStatus = "unverified-source-field" }
quests[26493] = { id = 26493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There's Somebody Out There Who Wants It", description = "So, while you're already all sweaty from doing all that other stuff, I was thinking I might grab you for one more task.  You don't mind, do you?\n\nThe latest Science and Explosions journal just came in from Bilgewater Harbor, and there's this article about this hot new reagent.  Prices on the reagent are skyrocketing, and we're in prime position to capitalize!\n\n<Sassy leans over and whispers the details into your ear.>\n\nYou got that?  Good.  You can find the basilisks in a cave, far to the east.", sourceObjective = "Obtain 7 of Sassy's Secret Ingredient from Thrashtail and Ironjaw Basilisks in the Crystalvein Mine.", progress = "I hope you used the extraction procedure we discussed.", completion = "Great!  These look... disgusting.  But probably pretty valuable.  Let's get to splitting these up.  Some for me, some for Jasper, some for Chabal...", sourceObjectiveStatus = "unverified-source-field" }
quests[26494] = { id = 26494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixmaster Jasper", description = "Mind giving some of this stuff to Jasper, over by the luxury suites?  I'm sure he can find some use for it.\n\nThanks, {name}!", sourceObjective = "Bring Sassy's Samples to Mixmaster Jasper in Hardwrench Hideaway.", progress = "Hey, is that the stuff?  From the magazine?", completion = "I'll file these away for now.  Maybe we can experiment later.\n\n<Jasper looks over at you.>\n\nYeah, you'll do.", sourceObjectiveStatus = "unverified-source-field" }
quests[26495] = { id = 26495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chabal", description = "Chabal, that troll over by the botanical gardens/biological weapons lab, is a special guest.  He's a representative of the Zandalari trolls, and has traveled quite far to stay with us.\n\n<Sassy places some of the items you've collected in a small parcel and hands it to you.>\n\nHere, give this to him.  Tell him that the Zandalari are always welcome at Hardwrench Hideaway!  And mention that referrals are key to maintaining our business!", sourceObjective = "Bring Sassy's Largesse to Chabal in Hardwrench Hideaway.", progress = "Care to explain yourself, {class}?", completion = "<The troll looks into the package.>\n\nYou have my thanks.\n\nI have been waiting for you to approach me, {race}.  I have identified you as the most promising {race} here in this strange town.  I have a task for you, if you would be willing to take it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26496] = { id = 26496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down with the Vilebranch", description = "The Revantusk isn't the only tribe of foul trolls we're here to take care of! The Vilebranch have corrupted this land for years from their stronghold of Jintha'Alor.\n\nWe're done sittin' by in Aerie Peak twiddlin' our thumbs, if you haven't noticed. Doran Steelwing leads the charge against the Vilebranch from a camp the boys took just to the south. Speak with him and join the fight!", sourceObjective = "Find Doran Steelwing at Jintha'Alor in The Hinterlands.", completion = "Well met, {name}! We've got a lot of trolls to kill and only so many hands to do it with!", sourceObjectiveStatus = "unverified-source-field" }
quests[26497] = { id = 26497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vilebranch Scum", description = "The Vilebranch are a different tribe from the Revantusk, but the difference is academic. Far as we're concerned the only good troll is a dead troll!\n\nBut make no mistake, the Vilebranch are just as nasty even without the Horde's chain around their neck. They'll poison this whole land unless we take this stand and get rid of them\n\nYou can start with their witchdoctors and headhunters on the lower tier. Let me know when you've killed a fair share of 'em.", sourceObjective = "Kill 5 Vilebranch Witch Doctors and 5 Vilebranch Headhunters in Jintha'Alor.", completion = "Aye, we'll have these trolls cleared out yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26498] = { id = 26498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Vilebranch", description = "We're makin' good progress. Keep pressing on, and don't falter!\n\nThe Vilebranch berserkers fight like savage animals, whipped into a blood frenzy. Their shadowcasters summon foul spirits from beyond this world! This is why we're getting rid of these depraved creatures, {name}, never forget that.\n\nHead to the middle tier and kill the berserkers and shadowcasters!", sourceObjective = "Kill 5 Vilebranch Berserkers and 5 Vilebranch Shadowcasters in Jintha'Alor.", completion = "It won't be long until we're the only dwarves left breathing on these walls.", sourceObjectiveStatus = "unverified-source-field" }
quests[26499] = { id = 26499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stonefather's Boon", description = "With the Stonefather taken prisoner, our forces are demoralized. Normally any one of mine could take five times his number of stone troggs. But now....\n\nI want you to head out into the field surrounding the town. Plant Stonefather Oremantle's banner near my defenders. Grant them his boon and remind them of that for which they fight.", sourceObjective = "Grant the Stonefather's Boon to 12 Earthen Defenders.", completion = "You have my thanks, {name}. You've made all the difference, and the fate of these cowardly stone trogg ambushers is set in stone.\n\nNow we must get about the business of retaking Stonehearth.", sourceObjectiveStatus = "unverified-source-field" }
quests[26500] = { id = 26500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We're Surrounded", description = "Our war has been waged for longer than your kind counts time. Let us see if you can make a difference, {race}.\n\nThe stone troggs are a mistake of the titans. On your world they have succumbed to the Curse of Flesh. But here, in Deepholm, you see them in their true form.\n\nWe're surrounded. Maybe you could go out there and break a few troggs down for us. See what they're really made of?", sourceObjective = "Slay 12 Stone Trogg Ambushers.", progress = "Are you going to pull your fleshy weight, {race}?", completion = "Not a bad start, though you'll have to destroy more of them than that if you're going to rescue the Stonefather.\n\nA lot more.", sourceObjectiveStatus = "unverified-source-field" }
quests[26501] = { id = 26501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing the Way", description = "The stone troggs have found a way to burrow up from underneath our homes!\n\nI've sent our geomancers to seal all of the buildings, but they need these reagents and enough time out of battle to properly cast their rockslide rituals.\n\nWhen you're done, report to, Gravel Longslab, just to the north on the Fractured Front.", sourceObjective = "Help the Earthen Geomancers to get out of combat and then give them the Rockslide Reagents so that they can seal the Armory, Inn, Barracks, and Shrine.", progress = "I know that Crag Rockcrusher sent you, {race}. Are all of the entrances sealed in Stonehearth behind us?", completion = "This is good. We no longer need to worry about stone trogg attacks from the rear.\n\nLet's see what you can do for us on the front.", sourceObjectiveStatus = "unverified-source-field" }
quests[26502] = { id = 26502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Stones", description = "To the north lies the Fractured Front. That is where most of the heavy fighting is happening.\n\nGo into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults.\n\nWhen you have enough, take them to Clay Mudaxle. Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.", sourceObjective = "Collect 12 Thunder Stones.", progress = "<The older Earthen has cracks where the others do not, clearly ancient.>\n\nWhat are you supposed to be? Some kind of fleshy mistake? Cursed is what you are!\n\n<Clay spits dust.>\n\nMake yourself useful or get off of my front!", completion = "<Clay grumbles to himself.>\n\nThose'll do. Just put them down over there.\n\n<The Earthen looks you up and down with one eye and then spits dust onto the ground.>\n\nI'm going to have something for you to do in a moment. Maybe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26503] = { id = 26503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Assessing the Threat", description = "Damned worthless gnolls are up to no good. I can feel it in my bones. Gnoll activity in the area has tripled in the past two weeks. I fear they might be mounting up to make an assault on Lakeshire.\n\nI need you to head to each of the gnoll camps of this area and gather any information that you come across. Check the camps directly north of here, east of here and southeast of here. Bring back whatever you find.", sourceObjective = "Steal the Gnoll Battle Plans, Gnoll Orders and Gnoll Strategy Guide.", progress = "Did you find the gnoll plans?", completion = "I knew it! Looks like Yowler is behind this uprising - which is incredible, because we keep killing gnolls named Yowler. I don't know how many sons the original Yowler had, but it's got to be close to a hundred.\n\nWell, looks like we got ourselves another Yowler to kill.\n\nMagistrate Solomon must be notified.", sourceObjectiveStatus = "unverified-source-field" }
quests[26504] = { id = 26504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: Redridge Gnolls", description = "By order of the Stormwind Royal Guard, all gnolls of the region known as Three Corners in the southwestern corner of Redridge Mountains, are wanted dead.\n\nShould you dispatch of the gnolls of the region, report your victory to Watch Captain Parker at Tower Watch.", sourceObjective = "Kill any 15 Redridge Gnolls in the Three Corners region of Redridge Mountains.", completion = "A job well done deserves a reward, wouldn't you say?\n\nDon't spend this all in one place, {class}. Better to spread it around, if you catch my drift.", sourceObjectiveStatus = "unverified-source-field" }
quests[26505] = { id = 26505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parker's Report", description = "<Watch Captain Parker hands you a report.>\n\nHere it is, {name}. Take my report to Lakeshire, located north of this tower, and deliver it to Magistrate Solomon. Inform him that we need a more comprehensive solution for dealing with the gnolls. Suggest explosives. Lots of explosives.\n\nAnd stick to the road if you know what's good for you.\n\nWhat's good for you is staying alive, by the way. In case you didn't know what was good for you. You now know... Oh never mind!", sourceObjective = "Deliver Parker's Report to Magistrate Solomon at Lakeshire in Redridge.", progress = "Where did I put my monocle?! Conacher is that you?", completion = "<Magistrate Solomon puts on his monocle.>\n\nOh, you're not Conacher. What have you got there?\n\n<Magistrate Solomon takes Parker's report from you.>\n\nOh for pity's sake. Yowler? AGAIN?", sourceObjectiveStatus = "unverified-source-field" }
quests[26506] = { id = 26506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Franks and Beans", description = "I need your help, {race}! Our rations have run out and the guards are getting hungry. They're clamoring for my world famous franks and beans, but I have no ingredients on hand. Would you be a darling and help me out?\n\nI need some goretusk kidneys, condor giblets, and tarantula eyes. You'll find goretusks, condors and tarantulas near this tower. Just look around!", sourceObjective = "Collect 4 Tarantula Eyes, 4 Condor Giblets and 4 Goretusk Kidneys.", progress = "Have you gotten my ingredients?", completion = "PERFECT! I'll put these in the pot right away. Dinner should be ready in a few hours.\n\nThank you, darling!", sourceObjectiveStatus = "unverified-source-field" }
quests[26507] = { id = 26507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Petrified Delicacies", description = "Petrified bats.\n\nElementals of that size are picky. You're not likely to find anything better easily.\n\nTo the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory.\n\nI must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.", sourceObjective = "Gather 12 Petrified Stone Bats for Pebble.", progress = "<Pebble starts to look up at you, eyes glowing faintly, growing rounder and larger every moment.>", completion = "<Pebble leaps upon the pile of petrified bats and rolls around in them, seeming to forget that you exist entirely. Perhaps for the best, if Kor's warnings are to be trusted.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26508] = { id = 26508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nida's Necklace", description = "My friend Nida lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", sourceObjective = "Find Nida's Necklace.", progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister {class}... you are very kind!  My kitty thanks you too - isn't that right Effsee?", sourceObjectiveStatus = "unverified-source-field" }
quests[26509] = { id = 26509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", sourceObjective = "Kill Bellygrub and take Bellygrub's Tusk.", progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, {name}, you have done me a great service.  The garden shall be in full bloom this season!", sourceObjectiveStatus = "unverified-source-field" }
quests[26510] = { id = 26510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Must Prepare!", description = "More of our citizens go missing every day. We think the gnolls are responsible, but we have no idea where they are taking them! If you are to help us defeat the gnolls and find our people, you must be properly equipped. Unfortunately, we are all out of gnomecorders. Without a gnomecorder, there is no way for us to communicate with you when you are in the field.\n\nOur last good gnomecorder was stolen by marauding murlocs last week. You will have to go to Lake Everstill, east of here, and recover it!", sourceObjective = "Recover the Gnomecorder.", progress = "Have you recovered the gnomecorder?", completion = "Excellent! Let me make a few adjustments here and we should be good to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[26511] = { id = 26511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lake Everstill Clean Up", description = "Headed out to Lake Everstill? You'll be happy to know that we currently have a bounty on murlocs. Kill as many as you can and be rewarded! Any murloc will do. All you need to do is kill indiscriminately.\n\nYou'll find Lake Everstill directly east of Lakeshire. It's the lake. Has water in it... Any of this ring a bell?", sourceObjective = "Kill any 10 Murlocs in Lake Everstill.", completion = "That ought to teach those murlocs a lesson. Hopefully the next time they decide to raid our town they'll think twice.\n\nWe both know that won't happen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26512] = { id = 26512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuning the Gnomecorder", description = "The gnomecorder looks to be in working order. I've got you all hooked up, now we just need to tune the gnomecorder for reception.\n\nHead north out of Lakeshire and follow the road up to the graveyard. Once you reach the graveyard I'll attempt to transmit.", sourceObjective = "Go to the Lakeshire Graveyard to tune the Gnomecorder.", completion = "<The gnomecorder crackles and pops.>\n\nCan you hear me, {name}? Is this thing on? Ah, yes, I see you there now.\n\nLet's get to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[26513] = { id = 26513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like a Fart in the Wind", description = "We were raided last night, or perhaps it was the night before. I'm not really sure when it was as I haven't had a wink of sleep in three days. I'm probably delusional at this point.\n\nListen, gnolls raided our supply stores and took off with everything! Just like a fart in the wind, they were in and they were OUT! My soldiers saw them running back towards the canyons, northwest of here. Recover our supplies, {class}!", sourceObjective = "Recover 8 Redridge Supply Crates.", progress = "Did you recover the supplies?", completion = "Thank you, citizen. Without you, we would have starved or worse, been forced to go out and get food for ourselves.", sourceObjectiveStatus = "unverified-source-field" }
quests[26514] = { id = 26514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canyon Romp", description = "<The gnomecorder hums.>\n\nThe first order of business is a romp through the Redridge Canyons, directly north of Lakeshire. Kill every gnome that you see... woops, did I say gnome? I meant gnoll. Kill every GNOLL that you see and take their collars as proof of deed.\n\nI must warn you, {name}; while you are out there, watch out for ettins. My scouts have reported seeing huge, bloodthirsty ettins roaming the canyons lately. Stay out of their way if you want to remain alive.\n\nSolomon out. I'll be in touch.", sourceObjective = "Collect 10 Redridge Gnoll Collars.", progress = "Did you recover those collars?", completion = "<The gnomecorder crackles and pops.>\n\nGood work, {name}. I've just been handed some important information. It would appear that our most hated enemy, the Blackrock orcs, have wised up...\n\n\n\nI've transferred a few silver over to you for the gnome, erm, gnoll kills.", sourceObjectiveStatus = "unverified-source-field" }
quests[26515] = { id = 26515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ongo'longo's Revenge", description = "I've got a plan to pit troll against troll.\n\nThe Vilebranch have a big ol' dire troll locked up in a pit with some flimsy-lookin' chains. I've seen those things fight, and there's no way those'll hold if that big brute gets swingin' mad!\n\nI want you to find the dire troll and fight him, {name}. Don't kill him... just smack him around til' he's seein' red, then let him break free and get out of his way! He'll be a big pain for the Vilebranch.", sourceObjective = "Fight Ongo'longo until he breaks free.", completion = "Ain't that a hoot! Wish I could've seen it myself.", sourceObjectiveStatus = "unverified-source-field" }
quests[26516] = { id = 26516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nDon't forget you're not just fighting trolls here, {name}. You're fighting dark and evil forces that'll churn this land into ash if we let them live!\n\nShow no mercy!", sourceObjective = "Kill 5 Vilebranch Blood Drinkers and 5 Vilebranch Soul Eaters in Jintha'Alor.", completion = "We've cleared straight through 'em! Jintha'Alor is as good as wiped out!", sourceObjectiveStatus = "unverified-source-field" }
quests[26517] = { id = 26517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summit of Fate", description = "You have to go to the summit now, {name}. Our warriors won't go past the final gates. They say it's still as a tomb; not a sound, not a breath, not a hint of motion.\n\nThey think it's a trap, but based on what you've brought me, I'm worried it's something even more sinister. Go to the altar, investigate what happened... and bring me back ANY sort of mystical object or dark idol you find! Do you hear me?", sourceObjective = "Collect 8 Spider Idols from the Vilebranch at the summit of Jintha'Alor.", progress = "What did you find?", completion = "Dead? All of them, around the altar? And you found these spider idols on them...\n\nIt's Shadra. The Spider Loa! They're trying to tap her power!", sourceObjectiveStatus = "unverified-source-field" }
quests[26518] = { id = 26518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heads Up", description = "Umboda Three-Heads is one o' the biggest trolls you'll see around. He's a savage butcher, takin' heads for his own collection, dwarf and troll alike! It's time he got what he deserved.\n\nLook for the big brute on the lower terraces, and you take his own head right back here!", sourceObjective = "Defeat Umboda Three-Heads and collect his head.", progress = "Let's see it!", completion = "That's one ugly mug. Maybe he was takin' other heads tryin' to find a prettier one!", sourceObjectiveStatus = "unverified-source-field" }
quests[26519] = { id = 26519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Who Controls the Ettins", description = "You've stumbled upon a gnoll document. The gnoll that wrote this propaganda is semi-literate:\n\nBROTHERS OF YOWLER, HEAR DIRTPAW! DIRTPAW GIVEN ORB FROM ORCS! DIRTPAW CONTROL ETTIN THINGS! DIRTPAW CRUSH HUMIES! COME GET DIRTPAW PAW-O-GRAPH IN RETHBAN CAVE. CAVE IS WEST, HIDDEN IN CANYON!\n\n<There's a paw print as the signature.>\n\n<There also appears to be a bite taken out of the scroll.>\n\nYou should probably investigate.", sourceObjective = "Kill Ardo Dirtpaw.", progress = "<The orb emanates powerful magic.>", completion = "<The orb hisses as you touch it.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26520] = { id = 26520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Foreman Oslow", description = "<Upon touching the orb you hear a faint click.>\n\n<You remove the orb from the pedestal.>\n\nYou now control the orb, therefore you now control the ettins. Maybe you can use an ettin to remove the huge boulder currently crushing Foreman Oslow over at Lakeshire. Find an ettin and use the orb on the ettin. Then head over to Lakeshire.", sourceObjective = "Use the Ettin Control Orb to control an Ettin and then use the Ettin Control Orb on your Subdued Canyon Ettin to lift the Huge Boulder off of Foreman Oslow at Lakeshire.", completion = "You used an ettin to remove the boulder that was crushing Foreman Oslow? Incredible work, {name}! Oslow will be grateful once he regains his composure.", sourceObjectiveStatus = "unverified-source-field" }
quests[26521] = { id = 26521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. We won't tolerate their foul hexes and dark magic.\n\nIt's time to send a message, and tear down their defenses, all at once! Take this torch, {class}. Set fire to their tiki masks and watch 'em burn. They'll know the Wildhammer want them gone when they see their dark idols consumed!", sourceObjective = "Use the Tiki Torch to set fire to 8 Tiki Masks at Jintha'Alor.", completion = "The elements dance, and fire consumes. Let the flame show 'em the cost of their wickedness!", sourceObjectiveStatus = "unverified-source-field" }
quests[26523] = { id = 26523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All That Skitters", description = "There's somethin' I've noticed up there... Jintha'Alor's full of spiders. Small ones about as big as yer hand. Not an unusual sight for the Hinterlands, but somethin's amiss.\n\nTo be honest, I don't trust the trolls to keep pets. They're up to somethin'. I need you to bring me some of those spiders. Keep 'em alive if you can, and we'll see what the spirits tell me...", sourceObjective = "Collect 8 Skittering Spiderlings in Jintha'Alor.", progress = "Let's see what you've got.", completion = "By Kurdan's beard... these don't look like any spiders I've seen before. Dark magic's at work here.", sourceObjectiveStatus = "unverified-source-field" }
quests[26524] = { id = 26524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Vessels", description = "The Vilebranch trolls here were always worshippers of the foul god Hakkar, the loa of blood. He was a sick and twisted entity that nearly broke through to our world, but he was defeated long ago.\n\nThe Vilebranch are still stirring their dark cauldrons, ones they filled with blood years before. They're either holding onto hope for a long-dead spirit, or they're up to something new and just as sinister.\n\nGet me those vessels, {name}. We need to examine them with the spiders and see just what's going on here!", sourceObjective = "Collect 5 Vessels of Tainted Blood from Jintha'alor.", progress = "Be careful near those cauldrons, {class}. The Vilebranch won't give them up easily!", completion = "This isn't just blood... it's venom!\n\nSpiders... venom... I hope I'm wrong about my hunches here, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26525] = { id = 26525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venomous Secrets", description = "If the sacrifice has already been made, Shadra's presence is going to start creepin' into this realm. That cave's probably full of her spawn by now.\n\nDon't let them escape, {name}. Slay any of those vile spiders you find!", sourceObjective = "Kill 8 Spawn of Shadra.", completion = "Good riddance. May those horrid things never walk these lands again.", sourceObjectiveStatus = "unverified-source-field" }
quests[26526] = { id = 26526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunt the Keeper", description = "Shadra the spider loa... the venom queen, a spirit of darkness and death! If there's been a sacrifice, they're trying to bring her forth as a last-ditch effort.\n\nIf the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", sourceObjective = "Kill Morta'gya the Keeper and obtain the Tablet of Shadra.", progress = "Be sure you search her body. I don't want any traps laid by the Vilebranch to be hidden by their deaths.", completion = "A tablet! If I can read this... this is a ritual to summon Shadra herself into this world, and a list of the idols needed.\n\nYou've done a good job slaying the keeper and getting ahold of this, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26527] = { id = 26527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphon Master Talonaxe", description = "I'd smash this tablet to bits if I had the right, but that's not for me to decide. Gryphonmaster Talonaxe needs to see this.\n\nYou've got to return to Aerie Peak with the tablet. Gryphon Master Talonaxe is in the aviary, tending to the gryphons.\n\nBe swift... and don't let that tablet leave your grasp for a moment!", sourceObjective = "Deliver the Tablet of Shadra to Gryphon Master Talonaxe.", sourceObjectiveStatus = "unverified-source-field" }
quests[26528] = { id = 26528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eye of Shadra", description = "Gryphon Master Talonaxe has sent me here to deal with Shadra, the Venom Queen. The conquest of Jintha'Alor isn't enough... the trolls could regroup and summon this creature later, when we're not expecting it.\n\nWe'll gather the artifacts first, pull Shadra into this world on our own terms, and put our hammers to that foul creature. I'll need you to help find the artifacts, and put a hurt on the rest of the trolls while you're at it.\n\nWe first need the Eye of Shadra, guarded in Agol'watha to the north.", sourceObjective = "Recover the Eye of Shadra from Agol'watha.", progress = "Was the tablet right? Did you find the eye?", completion = "Well done, {name}. We'll be knockin' on this bug's door in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26529] = { id = 26529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn. Hideous spiders the size of a dwarf, and twice as strong. Their venom is strong, {name}... don't get careless.", sourceObjective = "Collect the Fang of Shadra from the Creeping Ruins.", progress = "Have you got the fang?", completion = "There it is... only one left, lad.", sourceObjectiveStatus = "unverified-source-field" }
quests[26530] = { id = 26530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shell of Shadra", description = "The final piece is all we need to burn Shadra out for good.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nYou've got to climb that altar to the top and take her out! She'll have the Shell in her possession. Bring it back here.", sourceObjective = "Kill Qiaga the Keeper and collect the Shell of Shadra.", progress = "Do you have it?", completion = "This is it, lad! We're ready!", sourceObjectiveStatus = "unverified-source-field" }
quests[26531] = { id = 26531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Shadra", description = "Our best fighters are ready, we've got the idol assembled... it's time, {name}.\n\nHere's what we're gonna do. You'll travel southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples, fighting through the trolls guardin' them.\n\nWhen you do that, Shadra will emerge into our world, and we'll be right there waiting for her with fury in our hearts. Talk to my boys on the scene as soon as you've performed the ritual!", sourceObjective = "Use the Idol of Shadra at the Northwestern, Southwestern, and Eastern Temples in Shadra'Alor.", progress = "Are y'ready?", completion = "Talonaxe and the boys are right behind. Let's do this!", sourceObjectiveStatus = "unverified-source-field" }
quests[26532] = { id = 26532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadra the Venom Queen", description = "No time to waste, {name}! She's comin' out of the water right now!\n\nGryphon Master Talonaxe is comin' right now with the boys, let's show that bug what for!", sourceObjective = "Kill Shadra the Venom Queen.", completion = "You've done a great thing for the Wildhammer today, {name}. I wish Falstad could've been here for that.\n\nOn behalf of the whole clan, I'd like to repay you for keeping these lands free from that foul shadow. You've earned this reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[26533] = { id = 26533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI'd like to get my hands on some, {race}.  Check the zombies to the southeast.", sourceObjective = "Obtain 5 vials of Zanzil's Mixture.", progress = "Excellent... you're not a zombie yet.  That's good.\n\nOh, umm... nothing.  It's just that... that was a potential risk.  Did I forget to warn you?", completion = "<Jasper carefully analyzes the strange compound.>\n\nThis mixture is... I don't understand it.  Perhaps we need to run some clinical trials.", sourceObjectiveStatus = "unverified-source-field" }
quests[26534] = { id = 26534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's See What You've Got, Zanzil", description = "Visitors to Hardwrench Hideaway sign a number of waivers upon arrival, one of which allows us to perform basic tests on them.  I'd say it's about time we invoked that clause again.\n\nActually, let's avoid poisoning our customers this time.  Better for business.\n\n<Jasper fills a pitcher with Zanzil's Mixture and some crushed ice.>\n\nThe Hideaway's southeastern tower serves as a temporary jail.  \"Hardwrench Hoosegow,\" we call it.  Anyways, give the prisoners a drink and tell me what happens.", sourceObjective = "Offer Jasper's Jungle Cooler to Gmurgl, Orgus, and Captain Bartholomew Softbeard.", progress = "Come back when that pitcher's empty, {name}.", completion = "You don't say!  Well, that certainly is interesting.  In that case...\n\nForget understanding how the stuff works!  I gotta get my hands on that recipe!", sourceObjectiveStatus = "unverified-source-field" }
quests[26535] = { id = 26535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe for Disaster", description = "I need Zanzil's recipe, now more than ever.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the other coast of the Cape, and snatch it for me!", sourceObjective = "Obtain Zanzil's Formulation from one of Zanzil's followers in the Ruins of Aboraz.", progress = "Did he use shimmerweed?  I'm guessing he used shimmerweed.\n\nNo wait... amberseeds!  It's gotta be amberseeds.", completion = "This is fascinating!  Just think of all the applications!\n\nJust so we're clear, I'm not thinking about using this to make an army of slaves or anything like that.  No, no... I'm much more interested in the ogre explosions!", sourceObjectiveStatus = "unverified-source-field" }
quests[26536] = { id = 26536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunder Falls", description = "Arnold and I have been fishing in and around Stormwind for years now.  That's the kind of time it takes to find a good fishing spot.  One of my favorites is called Thunder Falls.\n\nIt's just south of Stormwind in Elwynn Forest.  Best part about Thunder Falls is the violet perch.  I have never seen them anywhere else, only up there at the falls.  It's a bit of hike for me and Arnold to get out there these days though, do you think you could head up there and fetch some of those perch for us?", sourceObjective = "Catch 4 Violet Perch from Thunder Falls, south of Stormwind. Return to Catherine Leland with your catch once you are done.", progress = "Were you able to find the falls?", completion = "These perch look great {name}.  Why don't you join us for a fish fry tonight?", sourceObjectiveStatus = "unverified-source-field" }
quests[26537] = { id = 26537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter Them!", description = "I want you to go out there and I want you to finish them.\n\nBerserkers, Earthrenders, Deathriders... I don't care! I want those stone troggs shattered!", sourceObjective = "Slay any 12 stone troggs on the Fractured Front.", completion = "That's a good dent, but it's clear to me that we're going to have to handle this a slightly different way.", sourceObjectiveStatus = "unverified-source-field" }
quests[26538] = { id = 26538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Aid", description = "Many of our warriors didn't survive the Twilight attack on our air fleet. Those that did are swimming to the remains of the fleet, bleeding and badly burned. I need support from the shore to keep my men alive!\n\nThere should be some sort of doctor or medicine man inside of Dragonmaw Port who would be willing to help his fellow orcs out. Go ashore and see if you can bring some medical supplies back to the fleet!", sourceObjective = "Seek out a Medicine Man in Dragonmaw Port, somewhere near the shore.", progress = "Speak quickly! What do you want?\n\nDon't let the Warchief see us talking...", completion = "<Gregor bows respectfully to Zaela.>\n\nIf it is Zaela's wish, then you shall have your supplies. Just don't tell the Dragonmaw Warchief...", sourceObjectiveStatus = "unverified-source-field" }
quests[26539] = { id = 26539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stalled Negotiations", description = "The Warchief's whereabouts are unknown! But we have to keep his plan moving forward. {name}, you look like you can get things done.\n\nOur negotiations with the Dragonmaw have stalled. Their Warchief is... not what we expected. I need you to go in there and get negotiations back on track.\n\nMeet with Ornak on the shore, he'll fill you in.\n\nTalk to Horzog on deck here for quick transportation to the shore.", sourceObjective = "Speak with Ornak in Dragonmaw Port. Horzog can provide you with quick transportation to the shore.", completion = "I'm glad you're here, {class}. Perhaps a seasoned veteran of the Horde's campaigns in Northrend and elsewhere can talk some sense into the Dragonmaw leadership...", sourceObjectiveStatus = "unverified-source-field" }
quests[26540] = { id = 26540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dangerous Compassion", description = "The red dragonflight represents the aspect of life. As such, their blood has healing properties.\n\nThis crate of bandages has been soaked in red dragon blood. It is the last of my supply. May it bring a speedy recovery to your warriors.\n\nWhatever the outcome of your negotiations here, do not forget that you have friends among the Dragonmaw.", sourceObjective = "Bring the Crate of Dragonmaw Bandages back to Warlord Krogg off the coast of Dragonmaw Port.", progress = "Do you bring any hope for our wounded?", completion = "Dragon's Blood!? We best not tell our red dragon allies that we've used these.\n\nStill, it's powerful magic... We'll have our fighting force back in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[26542] = { id = 26542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: The Hinterlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Travel to Aerie Peak in The Hinterlands and speak with Gryphon Master Talonaxe.", completion = "Welcome to Aerie Peak, {name}. On behalf of High Thane Falstad, I thank ye for comin' to help us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26543] = { id = 26543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clammy Hands", description = "Nothing tastes like fresh monstrous clam meat, {name}.  I have been so busy with work these past few weeks that I have not been able to make it out to the local clam spawning grounds.  Think you could run down there and gather some of those tasty treats for me?\n\nThe clams can be found near the shoreline on the eastern coast of Durotar.  Should be plenty right around the Orgrimmar docks.", sourceObjective = "Collect 10 Monstrous Clam Meat from the clams near the eastern shoreline, just south of Orgrimmar. Return to Razgar once you are done.", progress = "Were you able to find the clams?", completion = "Looks like you found the clams, {name}.  These will do nicely.", sourceObjectiveStatus = "unverified-source-field" }
quests[26544] = { id = 26544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They've Wised Up...", description = "<The gnomecorder crackles and pops.>\n\nIt would appear that the Blackrock orcs have finally wised up. I'm getting reports that they're joining forces with the gnolls and planning an attack. I want details, {name}!\n\nI need you to check out Rethban Caverns, located in the western region of Redridge Canyons. Look for orcs with dark skin. Kill any that you encounter and search their corpses for information.\n\nSolomon, out.", sourceObjective = "Recover the Blackrock Orc Missive.", progress = "What have you found out?", completion = "<The gnomecorder buzzes and whirs.>\n\nJust put the missive in the little compartment and I'll read it. I am fluent in orcish.\n\n<You hear a distraught yell in the background.>\n\nIt looks like these orcs are here under the direct command of Yowler. That means Yowler must have the orc invasion plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26545] = { id = 26545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yowler Must Die!", description = "<The gnomecorder hums.>\n\nYou need to find Yowler, {name}. He'll be located somewhere in the northern region of Redridge Canyons. Kill that mongrel and search his corpse for the Blackrock invasion plans. Should you succeed, bring the plans to me over at the town hall in Lakeshire.\n\nSolomon, out.", sourceObjective = "Kill Yowler and recover the Blackrock Invasion Plans.", progress = "Do you have the Blackrock invasion plans?", completion = "<Magistrate Solomon takes the plans from you and begins reading.>\n\nShadowhide army!? Damn those orcs to hell! These invasion plans speak of a massive build up of orcish and gnoll forces in the east. Looks like Gath'Ilzogg, the Blackrock general, is preparing to march his armies across Lakeshire and attack Stormwind directly!", sourceObjectiveStatus = "unverified-source-field" }
quests[26546] = { id = 26546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Razorbeak Friends", description = "Our clan reveres the gryphon as a sacred animal. They're majestic creatures of the skies, and more than just beasts; they're intelligent and cunning.\n\nSome say we keep them, but it's more of a friendship. If you want to befriend the Wildhammer here, first befriend our gryphons! Take this bag o' chow, it's nice and fresh. Our trained razorbeak gryphons wander the forests to the south of the aviary. Go on and feed a few of 'em for me, aye?", sourceObjective = "Use Gryphon Chow to feed 7 Trained Razorbeak gryphons.", completion = "Treat them with respect, and they'll treat you with it as well.\n\nGive 'em guff and you'll be out an eye!", sourceObjectiveStatus = "unverified-source-field" }
quests[26547] = { id = 26547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mangy Threat", description = "We do everything we can to protect our kin and our gryphons. That includes chasin' off predators, whether they be from the forest or from the Horde.\n\nI won't ask you to save us from two-legged monsters just yet. Mangy silvermane prowl the woods to the south where our gryphons range, and they're known to get 'em if they stray too low. Hunt a few of the silvermane and make sure they know our gryphons aren't food.", sourceObjective = "Kill 8 Mangy Silvermanes.", completion = "Much appreciated, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26548] = { id = 26548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out to the Front", description = "We need your help with somethin' more pressin', {name}.\n\nThe Horde's been gettin' bolder out here. They've moved in on our territory and started attackin' us outright. The Revantusk forest trolls are attackin' Stormfeather Outpost in broad daylight!\n\nI need you to help out. Talk to Guthrum Thunderfist just outside. He'll put you on a gryphon to Stormfeather Outpost. Kerr Ironsight will fill you in when you get there.", sourceObjective = "Speak with Kerr Ironsight at Stormfeather Outpost.", completion = "Good to see you out here! Let's get to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[26549] = { id = 26549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Madness", description = "Our last two negotiators haven't returned from speaking with the Dragonmaw Warchief. I think we might need to flex a little bit of muscle.\n\nThis time, I want YOU to accompany the negotiator. Their Warchief might think twice once he realizes the Horde is full of battle-hardened heroes like yourself.\n\nSimply escort our negotiator into the main hold in the center of Dragonmaw Port and look menacing.", sourceObjective = "Escort the Horde Negotiator to the main hall in Dragonmaw Port to meet with Warchief Mor'ghor of the Dragonmaw. Speak with Ornak on the coast if you lose your Negotiator.", progress = "{name}, I understand you're going to speak with our \"Warchief\" about joining your Horde.\n\nBe careful, {class}.\n\nSee me afterwards...", completion = "Wake up, {name}! We don't have much time.\n\nI rescued your gear for you.\n\nAt least now you've seen the foolishness of our leader first-hand. His blood is contaminated, his rage is unquenchable -- and he'll destroy us all trying to defeat the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[26550] = { id = 26550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the east.  Hir'eek will guide you from there.", sourceObjective = "Place the Gurubashi Incense in front of the Totem of Hir'eek, then listen to Zanzil's plot.", completion = "It is as I suspected.  Zanzil is too haughty to interfere with the squabbles between the Bloodscalps and the Skullsplitters.  No, he is playing a part in a grander scheme... Jin'do the Hexxer is using him to help bring Hakkar back to Zul'Gurub.\n\nIt's good that we found this out now, because it offers us a simple solution.", sourceObjectiveStatus = "unverified-source-field" }
quests[26551] = { id = 26551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return switfly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", sourceObjective = "Travel to the Ruins of Aboraz in the Cape of Stranglethorn and deal with Zanzil the Outcast.", sourceObjectiveStatus = "unverified-source-field" }
quests[26552] = { id = 26552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Chabal entrusted this task to you.\n\nThe portal lies in wait in front of you.", sourceObjective = "Use Zanzil's Portal and enter Zul'Gurub.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", sourceObjectiveStatus = "unverified-source-field" }
quests[26553] = { id = 26553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", sourceObjective = "Destroy High Priestess Jeklik's body before Zanzil can resurrect her.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", sourceObjectiveStatus = "unverified-source-field" }
quests[26554] = { id = 26554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", sourceObjective = "Pass through Zanzil's Portal.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", sourceObjectiveStatus = "unverified-source-field" }
quests[26555] = { id = 26555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", sourceObjective = "Deal with Zanzil the Outcast and High Priest Venoxis.\n\nIf you become lost or need to return to Zul'Gurub, speak with Chabal at Hardwrench Hideaway.", completion = "I ask you to slay Zanzil the Outcast, a lowly, hermetic exile of the Gurubashi, and what do you do?  You dash headfirst into the Gurubashi capital and eliminate one of their High Priests!  Very nearly two!  Only one word suffices to explain such a rash and foolhardy endeavor:\n\nHeroism.\n\nJin'do the Hexxer still walks within Zul'Gurub's walls, but he lost one of his legs when you crushed Jeklik.  Today's battle is ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[26556] = { id = 26556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Dumping Allowed", description = "Ever since those goblins took up refuge in Orgrimmar, they have been dumping all of their waste in our water supply.\n\nI have no idea what effect this is having on our local fishing supply, but I don't think it's good.  I have heard reports of a new mutated fish species spawning in that toxic pool near their camp.  A few specimens would really help me figure out what exactly is going on.\n\nCan you help me out?", sourceObjective = "Fish up 6 Toxic Puddlefish and return them to Razgar in the Valley of Honor once you are done.", progress = "Were you able to fish up a few specimens?", completion = "Nice work {name}.  These samples will help us figure out what is going on in that toxic soup over there.", sourceObjectiveStatus = "unverified-source-field" }
quests[26557] = { id = 26557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Staggering Effort", description = "I've fished sandy carp in Orgrimmar's local waters for years now.  Recently, I have noticed my bait is not working as well as it used to.  I suspect it has something to do with all the tauren that moved into the Valley of Wisdom.\n\nI spoke with one of their local fisherman and it just turns out their appetite has changed.  They are biting on stag eyes these days.  You should be able to find plenty of stags north of Orgrimmar, just outside the northern gate.", sourceObjective = "Slaughter a Stag north of Orgrimmar and use its eye as bait to catch a Sandy Carp in the Valley of Wisdom. Return to Razgar in the Valley of Honor once you are done.", progress = "Did the eye work as bait?", completion = "Outstanding!  Those sandy carp are picky eaters aren't they?", sourceObjectiveStatus = "unverified-source-field" }
quests[26558] = { id = 26558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoning Shadra", description = "The idol is prepared, {name}. I trust that you are as well?\n\nYou will go southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples.\n\nWhen you do that, Shadra will be summoned to this realm. The Deathstalkers and I will be along shortly to subdue and harvest her body. Speak with the lookout I've sent ahead once you've performed the ritual, and await my arrival.", sourceObjective = "Use the Idol of Shadra at the Northwestern, Southwestern, and Eastern Temples in Shadra'Alor.", completion = "Marnal draws close... and Shadra even closer. Prepare for bloodshed.", sourceObjectiveStatus = "unverified-source-field" }
quests[26560] = { id = 26560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorgensen", description = "I don't know where Krakauer or Danforth are, but Jorgensen was being held at Render's Camp, northwest of here. I was in the same crap filled cage with him before they relocated me to Alther's Mill.\n\nIf we're gonna get him out we'll need the key. A stone cold witch from hell known as Utroka the Keymistress holds on tight to that thing. We'll have to kill her if we're going to get Jorgensen's cage key. She's up north in the valley leading to the Burning Steppes.\n\nLet's go, kid.", sourceObjective = "Retrieve Jorgensen's Cage Key.", progress = "Messner! Damn, it's good to see a friendly face. Get me out of here!", completion = "I know where they're holding Krakauer and Danforth. We gotta hurry. They were prepping those two for a sacrifice!", sourceObjectiveStatus = "unverified-source-field" }
quests[26561] = { id = 26561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krakauer", description = "Krakauer is up on the chopping block as we speak! The orcs brought in a Gurubashi witch doctor to perform a dark ritual on him. We need to kill that troll to free Krakauer!\n\nLet's go! He's just inside the cave here. Hang a right at the first fork.", sourceObjective = "Kill Ritualist Tarak.", completion = "Wha... Where am I? What happened? Messner? Jorgensen?\n\nOH MY GOSH! We have to get to Danforth! It might already be too late!", sourceObjectiveStatus = "unverified-source-field" }
quests[26562] = { id = 26562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Last But Not Least... Danforth", description = "Danforth's being tortured on the other side of the cave. There's no telling what state he's in by now! We need to get over there and save him!\n\nOverlord Barbarius has the key to the lever holding Danforth up. We work together as a team and we can kill that bastard, Barbarius. Once Barbarius is dead, we use his key to get Danforth down and get out of here!\n\nReady?", sourceObjective = "Kill Overlord Barbarius and recover the Blackrock Lever Key. Use the Blackrock Lever Key to free Danforth.", progress = "Well look at that! The team's all here... everyone but Keeshan.", completion = "About damn time you sissies showed up. My arms were gettin' tired.", sourceObjectiveStatus = "unverified-source-field" }
quests[26563] = { id = 26563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Bravo Company", description = "I don't know who you are, <mister/missy>, but you've earned the respect and admiration of the Bravo Company. You've managed to save all our hides and kill a boatload of orcs in the process. Now we return the favor.\n\nGet back to Lakeshire and report to Colonel Troteman. We'll find Johnny and deliver the good news in person. With the Bravo Company back in action, these orcs don't stand a chance.", sourceObjective = "Report to Colonel Troteman at Lakeshire in Redridge.", completion = "<Colonel Troteman salutes.>\n\nUnbelievable work, {name}. You've managed to rescue the entire Bravo Company from the clutches of the Blackrock orcs? With Keeshan's team rescued and Keeshan's belongings returned, there's no way Keeshan could refuse us.", sourceObjectiveStatus = "unverified-source-field" }
quests[26564] = { id = 26564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fixer Upper", description = "<Clay sneers at you and makes a sound much like two stones rubbing against each other.>\n\nThey've smashed all of our catapults. I've been trying to get this one working, but no luck so far.\n\nMaybe you'd like to make yourself useful. Head out onto the front and grab me any spare parts you come across.\n\nYou think you can handle that, flesh bag?", sourceObjective = "Collect 6 Catapult Parts.", progress = "Well? I don't have all day.", completion = "Well then. Maybe you're okay after all.\n\nAlright, alright... don't get all bent out of shape. Just give me a few moments with these parts.", sourceObjectiveStatus = "unverified-source-field" }
quests[26565] = { id = 26565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Furious Catch (REMOVED)", description = "Are you up for a challenge, {name}?  Good, I was hoping you would be.  The southfury river flows just west of Orgrimmar and your challenge can be found within it's mighty flow.\n\nWe are looking for a furious pike.  This mighty fish used to be prevalent in these areas but ever since the floods hit, they have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.", sourceObjective = "Catch a Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done.", sourceObjectiveStatus = "unverified-source-field" }
quests[26566] = { id = 26566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Triumph of Gnomish Ingenuity", description = "We will need all the weapons, inventions, and soldiers we can get in order to defeat Razlo Crushcog and his followers.\n\nOver to the northeast, you'll find Engineer Grindspark, one of a new generation of brilliant gnomish minds. Why, he hasn't had an explosion in over three prototypes!\n\nBut enough bragging. Engineer Grindspark is working on a bot that he says will help clean up the toxic airfield. You should introduce yourself to him and see if he needs any help testing it.", sourceObjective = "Speak with Engineer Grindspark in New Tinkertown.", completion = "So Mekkatorque himself has heard of my little project? Splendid! I've almost finished my latest prototype, but maybe you can help me chase down those last few parts.", sourceObjectiveStatus = "unverified-source-field" }
quests[26567] = { id = 26567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "John J. Keeshan", description = "You ever heard of John Keeshan, {name}? I was his commanding officer throughout all three great wars. Let me tell you, that man has killed more orcs than any man alive. If anyone can stop the Blackrock orc invasion, it's JOHN J. KEESHAN. We need to get him to help us or Lakeshire will be nothing more than a mound of rubble and ash after that massive Blackrock army marches through to Elwynn.\n\nI heard he was fighting in the underground fight club at the Lakeshire inn. Find him and tell him everything you know.", sourceObjective = "Enlist the help of John J. Keeshan at the Lakeshire Inn in Lakeshire.", completion = "Help you? Help these people? These people that would rather spit on me than crack a smile?", sourceObjectiveStatus = "unverified-source-field" }
quests[26568] = { id = 26568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Ain't My War", description = "They asked me to fight in those wars. I didn't ask them! I did what I had to do to win. So I end up getting captured by those filthy, crap-swilling, maggot orcs and for five long years they used me as a toilet. Finally I break out and head back to my hometown and what do I get? People spitting on me, protesting me, calling me a baby orc killer and all kinds of vile crap!\n\nNo, I don't think I'll be helping you. You go back to Troteman and you tell him that this ain't my war.", sourceObjective = "Return to Colonel Troteman.", completion = "<Troteman sighs.>\n\nI'm not giving up on him, {name}, and I'm not giving up on Redridge. We need to boost his spirits... Rouse the slumbering monster within him!", sourceObjectiveStatus = "unverified-source-field" }
quests[26569] = { id = 26569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying Equipment", description = "Ah, my savior! I've heard that you're on a mission to save Lakeshire... and my bridge. Yep, worked too damned long on that thing to let it get destroyed by an army of marauding orc monsters!\n\nListen, if you're headed up north towards Render's Camp, would you do me a solid and get me some spyglasses from the Blackrock trackers up there? I could sure use 'em for my new surveying gear.", sourceObjective = "Recover 5 Blackrock Spyglasses.", progress = "Did you recover the spyglasses?", completion = "Fantastic work, {name}! These will come in handy for our next project, the Lakeshire SUPER BRIDGE, meant to traverse the length of Lake Everstill. It should be done in 20 or so years. Give or take a decade or two.", sourceObjectiveStatus = "unverified-source-field" }
quests[26570] = { id = 26570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Render's Army", description = "Heading up north, eh? How about you wage your own little war against those Blackrock monsters? What do you say, {name}?\n\nKill any Blackrock orc that you see at Alther's Mill or Render's Camp. Kill until your skin turns red from their blood splatter and then come back to me and I'll pay you handsomely.\n\nIt might not stop the Blackrock invasion, but it'll be sure to put a kink in their plans.", sourceObjective = "Kill any 25 Blackrock Orcs in Alther's Mill or Render's Camp.", completion = "You've probably bought us another day, maybe two. Nice work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26571] = { id = 26571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of War", description = "What I'm about to ask of you isn't going to be easy to accomplish, {name}. Keeshan left everything back there in that orc prison, and I'm not just talking about his soul or his will to live.\n\nIf we're going to get Johnny ready for war, we need to recover his prized possessions. The orcs now hold Keeshan's bow and his survival knife.\n\nHead to Alther's Mill, east of here and look for two orc lieutenants, Murdunk and Homurk. They've got Keeshan's gear. Get it back.\n\nI'll be in touch via gnomecorder.", sourceObjective = "Recover Keeshan's Bow and Keeshan's Survival Knife.", progress = "Did you terminate Murdunk and Homurk?", completion = "<The gnomecorder buzzes with energy.>\n\nCome in, {name}. Do you copy? Troteman here! Great job on getting Keeshan's weapons back! Now there's one final mission you have to run. Are you up to the challenge?", sourceObjectiveStatus = "unverified-source-field" }
quests[26572] = { id = 26572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Golden Opportunity", description = "You heard of the golden stonefish, {name}?  The thing with these fish is that they can't be caught by normal means.  They have jaws so strong that they snap right through any hooks or lures you try to use on 'em.\n\nYou can find a number of them in Thunder Ridge, south of Orgrimmar.  That ridge used to be full of thunder lizards, but they all drowned in the flood.\n\nTake my knife, swim down there and cut off their tails.  You should be able to use the tail to zap any stonefish you find.", sourceObjective = "Use Razgar's Fillet Knife to cut off a Drowned Thunder lizard Tail in Thunder Ridge, south of Orgrimmar. Once you have the tail, use it near a Golden Stonefish to kill it. Return to Razgar in the Valley of Honor once you are done.", progress = "How did it go down there?  Any luck with the tails and the stonefish?", completion = "Nice one, {name}!  I tell ya, golden stonefish are not easy to come by so this is a nice treat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26573] = { id = 26573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "His Heart Must Be In It", description = "<The gnomecorder clicks.>\n\nHis gear alone won't be enough, {name}. His heart must also be in this battle. To capture that, we need items of sentimental value. The Blackrock orcs of Render's Camp, located in the north, hold two such items that belong to Keeshan.\n\nGet up there and search their coffers for Keeshan's headband and a jade amulet left to him by his wife - who was brutally killed during a Blackrock orc invasion.\n\nBring them back to me should you succeed.", sourceObjective = "Recover Keeshan's Red Headband and Keeshan's Jade Amulet.", progress = "Did you locate the headband and amulet?", completion = "I hope with these items and with his crew all rescued he'll have a change of heart. We can't do this without Keeshan.", sourceObjectiveStatus = "unverified-source-field" }
quests[26574] = { id = 26574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adella's Covert Camp", description = "Lady Shandris has already asked for you to assist us further.\n\nAdella has struck out to the east, among the woodpaw gnolls, and established a foothold south of Camp Mojache. You are to report to her if you wish to assist Lady Shandris and the Alliance further.\n\nDon't stray too close to Camp Mojache... the Horde will not hesitate to attack. Keep to the south and look for our banners.", sourceObjective = "Report to Adella at Shadebough in Feralas.", completion = "Welcome to Shadebough, {name}. Lady Shandris sent word of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26575] = { id = 26575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rock Bottom", description = "I've one more favor to ask, fleshling.\n\nThere is a basilisk, much larger and much older than the rest. Though we normally fear nothing from their kind, this one has become so potent as to petrify some of my sons. This shall not be abided.\n\nFind Gorgonite to the east and slay him. He has lived much longer than necessary.", sourceObjective = "Kill Gorgonite.", completion = "Thank you, {race}. You've done all that I can ask of you. I shall impart my favor for you to the Stonemother.\n\nMay the stone beneath your feet hold you steady during your quest for the World Pillar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26576] = { id = 26576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady Hand", description = "Nearby to the north, you will find Terrath the Steady. He has taken upon the task of pulling the stone dragons back into the fold. We find ourselves repeating this trial every few hundred years... the stone dragons are fickle, and bend only to strength.\n\nTerrath is balanced and reasonable, but his goals may not be easily accomplished. Go to him. Appeal to the more balanced side of the Stonemother.", sourceObjective = "Speak to Terrath the Steady at the Pale Roost.", completion = "Greetings, {race}. I have been told of your coming. If you wish to aid me, then perhaps I can be of aid to you as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26577] = { id = 26577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocky Upheaval", description = "To the east, on the Crimson Expanse, you will find Gorsik. He embodies the more unstable and violent nature of our kind. He is neither friendly, nor trusting, but his word carries weight.\n\nProving yourself to Gorsik will go a long way towards proving yourself to the Stonemother.", sourceObjective = "Speak to Gorsik the Tumultuous upon the Crimson Expanse.", completion = "You are Diamant's chosen.\n\nSo small. So fragile.\n\nDo you realize that your actions shall be the basis by which your entire, \"Earthen Ring\" is judged? You truly think you can stand for so many?\n\nYou are a fool. A confident fool. We shall see if you are a capable fool as well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26578] = { id = 26578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomshrooms", description = "The rift to your world has poisoned our home. Corrupted it. Polluted it.\n\nThis expanse festers and grows. It becomes difficult to even see the purity of the rock beneath this filth.\n\nIf you are here to lend your aid, then go about cleansing this overgrowth. Look for the brightly glowing mushrooms that are growing faster than the others. They are the worst of the offenders.", sourceObjective = "Destroy 10 Doomshrooms.", completion = "You have appealed to Diamant. He is patient. Trusting. Perhaps too much so. You have much to prove if you wish my favor, {race}.\n\nStill, this is a start.", sourceObjectiveStatus = "unverified-source-field" }
quests[26579] = { id = 26579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gone Soft", description = "The fungal behemoths that surround us have succumbed to a weakness very similar to that that affects your kind. Their skin has grown soft. They no longer belong with the stone.\n\nKill them. We do not wish to see this infection spread.", sourceObjective = "Kill 8 Fungal Behemoths.", completion = "You carry with you a certain degree of potency. I can find some respect for such strength, especially in your kind.\n\nMy concerns are not yet abated. Not for the source of the overgrowth, and not for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[26580] = { id = 26580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familiar Intruders", description = "Fleshling. Some of your kind skitter among the rocks. Too cowardly to approach, too swift to be crushed.\n\nIf you wish my favor, deal with them. I tire of these games.", sourceObjective = "Speak to the \"fleshling\" intruders in the Crimson Expanse.", completion = "It is good to see you again, brother. I see that your efforts go well. The Stone Lords appear to be showing you some degree of trust.\n\nWe've come to help. We might be of some aid in tracking down the source of this sudden growth. I highly suspect your giant friend's aggressions are focused in the wrong direction.", sourceObjectiveStatus = "unverified-source-field" }
quests[26581] = { id = 26581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Head Full of Wind", description = "I'm no druid, but some of these mushrooms do not look to be naturally occurring. I know that our Stone Lord friend over there is eager to blame this on exposure to Azeroth, but I suspect more domestic causes.\n\nI saw some clouds of red mist to the northeast, near the water's edge. They seemed to be spurring new growth in their wake. Take one of my wind-devils with you and get me a sample from those clouds. You may have to stay close to the ground to spot them.", sourceObjective = "Bring Lorvarius' wind-devil to the clouds of red mist in the Crimson Expanse, near the water, and then return with a sample.", progress = "The fighting at the temple has quieted since you left. Whatever impression you're making, it seems to have helped at least that much.", completion = "You let the mist touch your skin? I hope there weren't any adverse affects.", sourceObjectiveStatus = "unverified-source-field" }
quests[26582] = { id = 26582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unnatural Causes", description = "This is most definitely magic in origin. Not even druidic. I suspect one among the stone troggs to the north.\n\nGo to Gorsik and point him in their direction. Hopefully this will help earn his favor.", sourceObjective = "Speak to Gorsik the Tumultuous in the Crimson Expanse.", completion = "The stone troggs? And I am to trust you at your word?\n\nI have no love for the Verlok anyway. Suspicion is more than enough reason to lay waste to them. We shall see if your word is true.", sourceObjectiveStatus = "unverified-source-field" }
quests[26583] = { id = 26583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Fungalmancer", description = "Their leader hides within his hole ahead. He is the one that has brought the plague upon the crimson expanse.\n\nHe must be killed.\n\nOne of your Earthen Ring companions is already inside. You should speak with her.", sourceObjective = "Speak to Earthmender Norsala, then kill Fungalmancer Glop.", progress = "I cannot fit inside. Our elementals are not up to the task.\n\nYou must see this done.", completion = "Well done, {race}.\n\nGorsik shall hear of your deed. Therazane shall hear of your deed.\n\nYou are quite vicious for one so small... and so soft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26584] = { id = 26584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaken and Stirred", description = "I have sent my brothers to assault the Verlok village from below. The Verlok will gather on their rocky ledges, as they always do to avoid our ire. When they do, we shall make the earth itself shake them until they fall at our feet below.\n\nThat is where you prove your use. When they fall to the ground amongst my brothers, make sure that they do not rise again.", sourceObjective = "Kill 8 Verlok Pillartumblers in the lower section of Verlok Stand.", completion = "Well done fleshling. Your presence complemented my brothers well.", sourceObjectiveStatus = "unverified-source-field" }
quests[26585] = { id = 26585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corruption Destruction", description = "If this disgusting growth is truly brought on by the Verlok, then their supplies will be in their village to the north. Bring them to me so that I can verify your claims.", sourceObjective = "Retrieve 8 bags of Verlok Miracle-Grow.", progress = "I await your proof, {race}...", completion = "So your words prove true. You have my gratitude, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26586] = { id = 26586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Bravo Company", description = "If you and Keeshan are going to defend Lakeshire, we're going to need to find his old battalion. Last I heard all of 'em - Messner, Jorgensen, Krakauer and Danforth - were captured by the Blackrock orcs. Now I don't know where they could possibly be or if they're even alive, but I'd be a damned fool if I didn't ask you to try and find 'em.\n\nSearch Alther's Mill, east of here, for any clues.", sourceObjective = "Search Alther's Mill for a member of the Bravo Company.", completion = "Keeshan? You mean JOHNNY'S ALIVE? You bet your sweet behind I'll help, but first you gotta get me out of this damned cage.", sourceObjectiveStatus = "unverified-source-field" }
quests[26587] = { id = 26587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Out is Hard to Do", description = "The key to this cage is stored in a pouch over at the worg den, just north of our location. The problem is that the pouch is resting safely atop a tree stump amidst a sea of bloodthirsty man-killing worgs.\n\nYou've got one shot to get that key without waking up any of those sleeping worgs. Head to the worg den and find a way into the center. Tread carefully and watch out for the Blackrock worg captain. Get the key and return to me.\n\nIf you got a pet, I'd recommend telling it to stay back!", sourceObjective = "Retrieve Messner's Cage Key.", progress = "Did you get the cage key?", completion = "IT'S PAYBACK TIME!", sourceObjectiveStatus = "unverified-source-field" }
quests[26588] = { id = 26588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Furious Catch", description = "Are you up for a challenge, {name}?  Good, I was hoping you would be.  The Southfury River flows just west of Orgrimmar and your challenge can be found within its mighty flow.\n\nWe are looking for a giant furious pike.  This esteemed fish used to be prevalent in these areas but ever since the floods hit, the big ones have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.", sourceObjective = "Catch a Giant Furious Pike in the Southfury River. The Southfury River can be found just outside Orgrimmar's western gate. Return to Razgar in the Valley of Honor once you are done.", progress = "Were you able to catch a giant pike?", completion = "{name}, you got one!  It's a rare day that I get to see such a strong, beautiful fish.", sourceObjectiveStatus = "unverified-source-field" }
quests[26589] = { id = 26589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Konu Runetotem. He has found signs of a disturbing illness.\n\nFollow the road west around the Twin Colossals to find Camp Ataya. Go in peace, {name}, and walk with the Earth Mother.", sourceObjective = "Travel to Feralas and speak with Konu Runetotem at Camp Ataya.", completion = "Peace, friend. I wish we could have met under less troubling circumstances.", sourceObjectiveStatus = "unverified-source-field" }
quests[26590] = { id = 26590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Holy Water of Clarity", description = "Hey, listen.  You don't look like any old tourist, and I'm in a bit of a pickle.  My cousin up north sent me this weird artifact, and I need your help to... ah... identify it.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  Rumor has it that whoever drinks from this spring is given a vision of clarity.\n\nSounds pretty promising, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", sourceObjective = "Obtain The Holy Water of Clarity from the Nek'mani Wellspring in the Cape of Stranglethorn.", progress = "<Flem's ears perk up as you approach.>\n\nThe Holy Water of Clarity?  Is it here!?", completion = "<The goblin downs the water in one gulp.>\n\nAhh... do you know how hard it is to get fresh water in Stranglethorn?  It's no wonder that the nagas guard their shrine so ferociously!\n\nOh, right... that artifact.  Clarity...\n\nI've got it!", sourceObjectiveStatus = "unverified-source-field" }
quests[26591] = { id = 26591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefront Triage", description = "You seem quick on your feet, {race}. I need someone to go out into the chaos of the front and patch up our injured.\n\nTake my kit. It's simple enough to use.\n\nHeal them before the stone troggs finish them off for good.", sourceObjective = "Patch up 10 Injured Earthen.", progress = "There are more injured Earthen on the front.", completion = "If you ever get tired of your being a {class}, come look me up. You seem very good with those fleshy hands of yours.", sourceObjectiveStatus = "unverified-source-field" }
quests[26592] = { id = 26592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diffractory Chromascope", description = "To properly identify this artifact, I will need tools for analysis.  A diffractory chromascope should suffice, I think.\n\nI already have the mithril casing, which surprisingly, is the hardest part to find.  We simply need two other pieces: a ruby and a sapphire.\n\nThere's pirates nearby, just to our south, and a bit farther to the east.  Pirates love treasure... why don't you see if you can find some gems for me?", sourceObjective = "Obtain a Bloodsail Ruby and a Bloodsail Sapphire.", progress = "<Flem's eyes sparkle.>\n\nAre those gems I see?", completion = "<Flem weighs the gems in his hands and nods in approval.>\n\nYes, these will do.  Now to perform the analysis...\n\n<The goblin clacks the gems together for a while, then looks up at you.>\n\nOh, you're still here?  You don't think I'm a fraud or something, do you?", sourceObjectiveStatus = "unverified-source-field" }
quests[26593] = { id = 26593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me.  Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt elder mistvale gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", sourceObjective = "Obtain 5 Mistvale Giblets from Elder Mistvale Gorillas.", progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?", sourceObjectiveStatus = "unverified-source-field" }
quests[26594] = { id = 26594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", sourceObjective = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.", progress = "Here here, {name}.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, {name}.  Now it's your turn to get paid...", sourceObjectiveStatus = "unverified-source-field" }
quests[26595] = { id = 26595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill-Collect", description = "There's three phases to debt collecting: asking nicely, asking forcefully, and something I like to call \"Phase Three\".\n\nUnfortunately, collecting during Phase Three is something that this old dog can't do any more.  That's why I employ so many cronies, stooges, mooks, goons, and noble adventurers like yourself!\n\nJuntz Fitztittle, Ephram Moonfall, and Maury Wilkins are hiding out on the eastern coast.  You should have no problem visiting them all in one trip... and bringing back their valuables.", sourceObjective = "Obtain Maury's Clubbed Foot, Fitztittle's Ratcheting Torque Wrench, and Ephram's Jeweled Mirror.", progress = "{name}, did you find those debtors?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, {name}!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with.", sourceObjectiveStatus = "unverified-source-field" }
quests[26596] = { id = 26596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Kalimdor", description = "I've been sent by the good people of Theramore to find loyal members of the Alliance who are willing to help Lady Jaina with some problems in Dustwallow.\n\nYou weren't really here working for the goblins, were you?\n\nThe path back to Dustwallow will take you through Ratchet.  Wait on the end of this pier for the next boat.  Once you get to Ratchet, speak with Gazlowe.  He'll point you in the right direction from there.\n\nUgh, I think I stepped on a fish!  And it flopped!", sourceObjective = "Ride the ship from Booty Bay to Ratchet, then speak with Gazlowe.", completion = "Yeah?  Whaddya need?", sourceObjectiveStatus = "unverified-source-field" }
